def point_type(name, fields=None, srid_map=None):
    """
    Dynamically create a Point subclass.

    Parameters
    ----------
    name : str
        The name of the subclass to create.
    fields : dict, optional
        Additional attributes to attach to each instance. Each key is
        an attribute name and the corresponding value is the default value
        to assign if not provided at construction time.
    srid_map : dict, optional
        Mapping of SRID values to either a two‑tuple `(x, y)` or a dict
        of keyword arguments that can be passed to the subclass constructor.
        A convenience ``classmethod`` ``from_srid`` is added to the class
        to instantiate an object from a given SRID.

    Returns
    -------
    type
        A new subclass of :class:`shapely.geometry.Point` with the given
        name and the specified additional fields.
    """
    from shapely.geometry import Point as BasePoint

    fields = fields or {}
    srid_map = srid_map or {}

    # Custom __init__ that forwards to the base Point constructor
    # and sets any extra fields.
    def __init__(self, x=None, y=None, *args, **kwargs):
        BasePoint.__init__(self, x, y, *args, **kwargs)
        # Set default fields first.
        for key, default in fields.items():
            setattr(self, key, default)
        # Override with any explicit keyword arguments.
        for key, value in kwargs.items():
            setattr(self, key, value)

    # Convenience classmethod to create an instance from an SRID.
    @classmethod
    def from_srid(cls, srid, **kwargs):
        if srid not in srid_map:
            raise ValueError(f"SRID {srid} is not defined in srid_map")
        source = srid_map[srid]
        if isinstance(source, tuple):
            return cls(*source, **kwargs)
        elif isinstance(source, dict):
            return cls(**{**source, **kwargs})
        else:
            raise TypeError("Values in srid_map must be tuples or dicts")

    attrs = {
        "__init__": __init__,
        "from_srid": from_srid,
    }

    # Add any additional fields as class attributes (defaults for all instances).
    for key, value in fields.items():
        attrs[key] = value

    return type(name, (BasePoint,), attrs)

def point_type(name, fields, srid_map):
    """
    Dynamically create a Point subclass.
    """
    class_attrs = {
        "_srid_map": srid_map,
    }

    def __init__(self, *coords, srid=None, **kwargs):
        if len(coords) < len(fields):
            raise ValueError(f"Expected {len(fields)} coordinates for {name}, got {len(coords)}")
        super().__init__(*coords)
        for field_name, value in zip(fields, coords):
            setattr(self, field_name, value)
        self.srid = srid
        for key, val in kwargs.items():
            setattr(self, key, val)

    class_attrs["__init__"] = __init__
    return type(name, (Point,), class_attrs)

