def parse_version(s: str) -> tuple[int, ...]:
    """
    Poor man's version comparison.

    Splits a version string on '.' and converts each component to an integer.
    Non-numeric parts are treated as 0. Leading and trailing whitespace is ignored.

    Examples:
        parse_version('1.2.3')  -> (1, 2, 3)
        parse_version('4.5')    -> (4, 5)
        parse_version('  10.01.2 ') -> (10, 1, 2)
        parse_version('2.0beta') -> (2, 0)
    """
    # Strip whitespace
    s = s.strip()
    if not s:
        return ()

    parts = s.split('.')
    version_numbers = []
    for part in parts:
        # Extract numeric prefix; ignore any trailing non-digits
        num = ''
        for ch in part:
            if ch.isdigit():
                num += ch
            else:
                break
        if num:
            version_numbers.append(int(num))
        else:
            # Treat non-numeric component as 0
            version_numbers.append(0)
    return tuple(version_numbers)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    # Use common separators (., -, _) to split, then extract numeric parts
    for sep in ('.', '-', '_'):
        s = s.replace(sep, '.')
    parts: list[int] = []
    for token in s.split('.'):
        # Keep only digits from each token
        digits = ''.join(ch for ch in token if ch.isdigit())
        if digits:
            parts.append(int(digits))
    return tuple(parts)

