def parse_version(s: str) -> tuple[int, ...]:
    parts = []
    num = 0
    in_num = False
    for ch in s:
        if '0' <= ch <= '9':
            num = num * 10 + (ord(ch) - 48)
            in_num = True
        else:
            if in_num:
                parts.append(num)
                num = 0
                in_num = False
    if in_num:
        parts.append(num)
    return tuple(parts)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    import os, sys
    if not cmd:
        return cmd
    if sys.platform != "win32":
        return cmd

    first = cmd[0]
    new_cmd = list(cmd)

    # Handle shebang on Windows
    if os.path.isfile(first):
        try:
            with open(first, "r", encoding="utf-8", newline=None) as f:
                first_line = f.readline()
                if first_line.startswith("#!"):
                    shebang = first_line[2:].strip()
                    parts = shebang.split()
                    if parts:
                        interpreter = parts[0]
                        interpreter_args = parts[1:]
                        new_cmd = (
                            [interpreter]
                            + interpreter_args
                            + [first]
                            + list(cmd[1:])
                        )
        except (OSError, UnicodeDecodeError):
            pass

    # Quote arguments for Windows CreateProcess
    def _quote(arg: str) -> str:
        if not arg or any(c in arg for c in " \t\n\v\""):
            # Surround with double quotes and escape internal quotes/backslashes
            escaped = '"'
            backslashes = 0
            for ch in arg:
                if ch == "\\":
                    backslashes += 1
                    escaped += ch
                elif ch == '"':
                    escaped += "\\" * (backslashes * 2 + 1) + ch
                    backslashes = 0
                else:
                    escaped += ch
                    backslashes = 0
            escaped += "\\" * (backslashes * 2) + '"'
            return escaped
        return arg

    return tuple(_quote(a) for a in new_cmd)

