def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize is None or maxsize <= 0:
        maxsize = 0  # effectively disabled
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            now = timer()
            # Purge expired entries
            for k in list(cache):
                _, exp, _ = cache[k]
                if exp <= now:
                    del cache[k]
            # Build lookup key
            key = args
            if kwargs:
                key = key + tuple(sorted(kwargs.items()))
            if typed:
                key = key + tuple(type(v) for v in args) + tuple(type(v) for v in kwargs.values())
            entry = cache.get(key)
            if entry is not None:
                result, exp, _ = entry
                if exp > now:
                    # Update last access time
                    cache[key] = (result, exp, now)
                    return result
                else:
                    # Expired, remove
                    del cache[key]
            # Compute new result
            result = func(*args, **kwargs)
            exp = now + ttl
            cache[key] = (result, exp, now)
            # Evict if cache exceeds maxsize
            if maxsize and len(cache) > maxsize:
                # Find least recently used entry
                oldest_key = None
                oldest_time = float('inf')
                for k, (_, _, last) in cache.items():
                    if last < oldest_time:
                        oldest_time = last
                        oldest_key = k
                if oldest_key is not None:
                    del cache[oldest_key]
            return result
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    from functools import wraps

    class CacheInfo:
        def __init__(self, hits, misses, maxsize, currsize):
            self.hits = hits
            self.misses = misses
            self.maxsize = maxsize
            self.currsize = currsize
        def __repr__(self):
            return f'{self.__class__.__name__}(hits={self.hits}, misses={self.misses}, maxsize={self.maxsize}, currsize={self.currsize})'

    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            for k in sorted(kwargs):
                key += (k, kwargs[k])
        if typed:
            key += tuple(type(v) for v in args)
            for k in sorted(kwargs):
                key += (type(kwargs[k]),)
        return key

    def decorating_function(user_function):
        cache = {}
        hits = misses = 0
        try:
            toplevelmaxsize = int(maxsize)
            if toplevelmaxsize < 0:
                raise ValueError("maxsize must be >= 0")
        except Exception:
            raise TypeError('maxsize must be an integer')
        if not isinstance(ttl, (int, float)):
            raise TypeError('ttl must be a number')

        @wraps(user_function)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = _make_key(args, kwargs, typed)
            now = timer()
            entry = cache.get(key, None)
            if entry is not None:
                result, expire_at = entry
                if expire_at > now:
                    hits += 1
                    # Move to the end to mark as recently used
                    cache.pop(key)
                    cache[key] = (result, expire_at)
                    return result
                else:
                    # Expired
                    del cache[key]
            # Miss
            misses += 1
            result = user_function(*args, **kwargs)
            expire_at = now + ttl
            if len(cache) >= toplevelmaxsize:
                # Evict least recently used item
                oldest_key = next(iter(cache))
                del cache[oldest_key]
            cache[key] = (result, expire_at)
            return result

        def cache_info():
            return CacheInfo(hits, misses, toplevelmaxsize, len(cache))

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorating_function

