def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(method):
        def wrapper(*args, **kwargs):
            cache_key = key(method, *args, **kwargs)
            if lock:
                with lock:
                    if cache_key in cache:
                        return cache[cache_key]
            else:
                if cache_key in cache:
                    return cache[cache_key]
            result = method(*args, **kwargs)
            if lock:
                with lock:
                    cache[cache_key] = result
            else:
                cache[cache_key] = result
            return result
        wrapper.__name__ = method.__name__
        wrapper.__doc__ = method.__doc__
        wrapper.__dict__.update(method.__dict__)
        return wrapper
    return decorator

def hashkey(self, *args, **kwargs):
    return hash((self.__class__, args, tuple(sorted(kwargs.items()))))

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    callback: the function to memoize
    cache: a mapping or object providing get/set interfaces
    key: function that produces a hashable cache key
    lock: optional context manager for thread‑safety
    """
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            cache_key = key(self, *args, **kwargs)
            # Try to retrieve from cache
            found = False
            if lock:
                with lock:
                    if isinstance(cache, dict):
                        if cache_key in cache:
                            value = cache[cache_key]
                            found = True
                    else:
                        try:
                            value = cache.get(cache_key)
                            found = True
                        except Exception:
                            found = False
            else:
                if isinstance(cache, dict):
                    if cache_key in cache:
                        value = cache[cache_key]
                        found = True
                else:
                    try:
                        value = cache.get(cache_key)
                        found = True
                    except Exception:
                        found = False
            if found:
                return value
            # Compute result and store in cache
            value = func(self, *args, **kwargs)
            if lock:
                with lock:
                    if isinstance(cache, dict):
                        cache[cache_key] = value
                    else:
                        cache.set(cache_key, value)
            else:
                if isinstance(cache, dict):
                    cache[cache_key] = value
                else:
                    cache.set(cache_key, value)
            return value
        return wrapper
    return decorator

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if lock:
                lock.acquire()
            try:
                try:
                    return cache[cache_key]
                except KeyError:
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
            finally:
                if lock:
                    lock.release()
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception into a readable string with a shortened traceback.
        """
        import traceback
        import os

        # Get the traceback object from the exception
        tb = getattr(e, "__traceback__", None)
        if tb is None:
            return f"{type(e).__name__}: {e}"

        # Extract frames and limit depth
        frames = traceback.extract_tb(tb)[:max_level]

        # Build the output list
        parts = ["Traceback (most recent call last):"]

        for frm in frames:
            # Shorten the file path
            if max_path_level > 0:
                parts_path = os.path.normpath(frm.filename).split(os.sep)
                if len(parts_path) > max_path_level:
                    filename = os.sep.join(parts_path[-max_path_level:])
                else:
                    filename = os.path.normpath(frm.filename)
            else:
                filename = os.path.normpath(frm.filename)

            parts.append(f'  File "{filename}", line {frm.lineno}, in {frm.name}')
            if frm.line:
                parts.append(f'    {frm.line.strip()}')

        # Append the exception type and message
        parts.append(f"{type(e).__name__}: {e}")

        return "\n".join(parts)

