def _getTargetClass(self):
    """Return the implementation class name currently in use, without any trailing 'Py' or 'Fallback'."""
    impl = getattr(self, "_impl", None)
    if impl is None:
        return None
    # Get the class name of the implementation instance.
    name = impl.__class__.__name__
    # Strip known suffixes.
    if name.endswith("Py"):
        name = name[:-2]
    elif name.endswith("Fallback"):
        name = name[:-8]
    return name

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Build graph of precedence constraints and indegree counts
    graph = {}
    indegree = {}
    for order in orderings:
        for i, a in enumerate(order):
            if a not in graph:
                graph[a] = set()
            indegree.setdefault(a, 0)
            for b in order[i+1:]:
                if b not in graph:
                    graph[b] = set()
                indegree.setdefault(b, 0)
                if b not in graph[a]:
                    graph[a].add(b)
                    indegree[b] += 1

    # Compute a deterministic key for each element: earliest (order index, position)
    keys = {}
    for j, order in enumerate(orderings):
        for k, elem in enumerate(order):
            t = (j, k)
            if elem not in keys or t < keys[elem]:
                keys[elem] = t

    # Topological sort using deterministic ordering based on keys
    result = []
    # Initialize list of nodes with zero indegree
    zero_nodes = [n for n, d in indegree.items() if d == 0]
    while zero_nodes:
        # Select node with smallest key
        best = zero_nodes[0]
        best_key = keys[best]
        for n in zero_nodes[1:]:
            nk = keys[n]
            if nk < best_key:
                best = n
                best_key = nk
        zero_nodes.remove(best)
        result.append(best)
        for m in graph[best]:
            indegree[m] -= 1
            if indegree[m] == 0:
                zero_nodes.append(m)
    return result

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.
    """
    if not orderings:
        return []

    # Record first appearance order index and position for each element
    first_order = {}
    first_pos = {}
    for o_idx, ordering in enumerate(orderings):
        for p_idx, elem in enumerate(ordering):
            if elem not in first_order:
                first_order[elem] = o_idx
                first_pos[elem] = p_idx

    # Build graph edges (u -> v) from consecutive pairs in each ordering
    adj = {}
    for ordering in orderings:
        for i in range(len(ordering) - 1):
            u, v = ordering[i], ordering[i + 1]
            adj.setdefault(u, set()).add(v)
            # Ensure all nodes appear in adj even if they have no outgoing edges
            adj.setdefault(v, set())

    # Compute indegree of each node
    indegree = {node: 0 for node in adj}
    for u, neighbors in adj.items():
        for v in neighbors:
            indegree[v] += 1

    # Use a heap to get deterministic order based on first appearance
    import heapq
    heap = []
    for node, deg in indegree.items():
        if deg == 0:
            heapq.heappush(heap, (first_order[node], first_pos[node], node))

    result = []
    while heap:
        _, _, node = heapq.heappop(heap)
        result.append(node)
        for neigh in adj[node]:
            indegree[neigh] -= 1
            if indegree[neigh] == 0:
                heapq.heappush(heap, (first_order[neigh], first_pos[neigh], neigh))

    return result

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Attempt to obtain the provided interfaces via the ``__provides__`` attribute
    try:
        provides = object.__provides__
    except AttributeError:
        # If the object is a class, try its class attribute
        if isinstance(object, type):
            provides = getattr(object, '__provides__', ())
        else:
            provides = ()
    # Normalise ``provides`` to a tuple and handle ``None`` values
    if provides is None:
        provides = ()
    from zope.interface.interfaces import IDeclaration
    return IDeclaration(tuple(provides))

