def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Determine which classes are superclasses of any other class in the list.
    to_remove = set()
    for c in classes:
        for d in classes:
            if c is d:
                continue
            try:
                if issubclass(d, c):
                    to_remove.add(c)
                    break
            except TypeError:
                # If either c or d is not a class, ignore the relationship.
                pass
    # Preserve original order, excluding classes marked for removal.
    return [c for c in classes if c not in to_remove]

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for cls in classes:
        if any(issubclass(cls, base) for base in result):
            # cls is redundant because an earlier base is a superclass
            continue
        result.append(cls)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    result = []
    n = len(classes)
    for i, cls in enumerate(classes):
        # Skip if any already kept class is a subclass of the current one
        if any(issubclass(res, cls) for res in result):
            continue
        # Skip if any later class is a subclass of the current one
        if any(issubclass(classes[j], cls) for j in range(i + 1, n)):
            continue
        result.append(cls)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        if not any(cls != other and issubclass(cls, other) for other in classes):
            result.append(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return a dictionary mapping attribute names to their descriptions.

    Keyword Arguments:
    all -- If True, include attributes from all base classes (excluding 'object'); otherwise only attributes
           defined directly on the class where this method is called.
    """
    results: dict[str, str] = {}
    # Determine which classes to inspect
    classes = [self.__class__] if not all else [
        cls for cls in self.__class__.mro() if cls is not object
    ]

    for cls in classes:
        for name, attr in cls.__dict__.items():
            # Skip private/internal attributes and methods
            if name.startswith("_"):
                continue
            if callable(attr):
                continue
            # Attempt to retrieve a description
            desc = getattr(attr, "description", None)
            if desc is None:
                desc = getattr(attr, "__doc__", "")
            if desc is None:
                desc = ""
            results[name] = desc
    return results

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = {}
    for name in dir(self):
        if not all and name.startswith('_'):
            continue
        try:
            value = getattr(self, name)
        except Exception:
            continue
        if callable(value):
            continue
        # Get description from the class descriptor if available
        desc = None
        cls_attr = getattr(self.__class__, name, None)
        if isinstance(cls_attr, property):
            fget = cls_attr.fget
            if fget and hasattr(fget, '__doc__'):
                desc = fget.__doc__
        elif hasattr(cls_attr, '__doc__'):
            desc = cls_attr.__doc__
        result[name] = desc
    return result

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    def _get_names(cls):
        return [
            k
            for k, v in cls.__dict__.items()
            if not k.startswith("_") and not callable(v)
        ]

    result = _get_names(self.__class__)
    if all:
        for base in self.__class__.__mro__[1:]:
            result.extend(_get_names(base))
    return sorted(set(result))

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Class-level attributes that are part of the interface
    interface_attrs = [
        name
        for name, value in vars(self.__class__).items()
        if not name.startswith('_')
        and not callable(value)
        and not isinstance(value, property)
    ]

    if all:
        # Include any instance-specific attributes not already in interface_attrs
        instance_attrs = [name for name in vars(self).keys() if name not in interface_attrs]
        return sorted(set(interface_attrs + instance_attrs))
    else:
        return sorted(interface_attrs)

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Use the instance's class to discover attribute names.
    # The `all` flag controls whether attribute names from base classes are included.
    attrs = set()
    # Determine which classes to inspect: the current class and optionally its base classes.
    classes_to_inspect = [self.__class__]
    if all:
        classes_to_inspect.extend(self.__class__.__mro__[1:])
    for cls in classes_to_inspect:
        # Add names from type annotations if present.
        if hasattr(cls, "__annotations__"):
            attrs.update(cls.__annotations__.keys())
        # Add names from the class dictionary that are not private and not callable.
        for key, value in cls.__dict__.items():
            if not key.startswith("_") and not callable(value):
                attrs.add(key)
    # Return a sorted list for deterministic ordering.
    return sorted(attrs)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        # Skip non-mapping items that are not interfaces or implements specs
        if isinstance(item, (tuple, list)) and not hasattr(item, "__implements__"):
            output.extend(item)
        else:
            output.append(item)
    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for arg in sequence:
        # Expand tuples, lists, sets, etc. but leave strings and other singular
        # objects (presumed to be interfaces or implementation specs) untouched.
        if isinstance(arg, (tuple, list, set, frozenset)) and not isinstance(arg, str):
            output.extend(arg)
        else:
            output.append(arg)
    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Ensure we can iterate over sequence even if it's a single element
    if not isinstance(sequence, (list, tuple, set)):
        sequence = (sequence,)

    for item in sequence:
        # If it's a tuple/list, decide whether to expand it or treat it as a whole.
        if isinstance(item, (list, tuple)):
            # A Declarion is typically a namedtuple; keep it intact.
            if hasattr(item, "_fields"):
                output.append(item)
            else:
                # Expand the tuple/list
                output.extend(item)
        else:
            output.append(item)

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        if isinstance(item, (list, tuple)) and not isinstance(item, (str, bytes)):
            _normalizeargs(item, output)
        else:
            output.append(item)
    return output

def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.
    """
    try:
        # Attempt to import the C optimization module
        return __import__("c_optimizations")
    except ImportError:
        # If the use of the optimizations is mandatory, re-raise the ImportError
        if globals().get("_C_OPTIMIZATIONS_REQUIRED", False):
            raise
        # Otherwise signal the unavailability with a false value
        return False

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    return not _c_optimizations_required()

def _c_optimizations_required():
    """
