def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is True (or truthy), we do not need C optimizations.
        # If it's False or falsy, C optimizations are required.
        return not bool(PURE_PYTHON)
    except NameError:
        # If PURE_PYTHON is not defined, default to requiring C optimizations.
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Clear the current context
    self.context = {}

    # Re‑initialise bin values
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # Reset each existing bin to the predefined initial value
        self.bins = {k: self.initial_value for k in self.bins}
    else:
        # Re‑create the bin structure
        self.bins = self.make_bins()

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    self.context = {}

    # Reinitialize bins
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # Attempt to fill existing bins with the provided initial value
        try:
            # If bins is a dict, set each key's value
            if isinstance(self.bins, dict):
                for k in self.bins:
                    self.bins[k] = self.initial_value
            # If bins behaves like a sequence, set each element
            elif hasattr(self.bins, "__len__"):
                for i in range(len(self.bins)):
                    self.bins[i] = self.initial_value
            else:
                # Fallback: just replace the bins object
                self.bins = self.initial_value
        except Exception:
            # On failure, reset bins using the factory method
            self.bins = self.make_bins()
    else:
        # If no initial value was given, re-create the bins
        self.bins = self.make_bins()

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context
    self.context = {}
    # Reinitialize bins
    if hasattr(self, "initial_value") and self.initial_value is not None:
        # If bins already exist, use their length; otherwise default to 1
        bin_count = len(self.bins) if hasattr(self, "bins") else 1
        self.bins = [self.initial_value] * bin_count
    else:
        # Fall back to factory method if available
        if hasattr(self, "make_bins"):
            self.bins = self.make_bins()
        else:
            self.bins = []   # default empty if nothing else is provided

def to_csv(self, separator=",", header=None):
    """Convert graph's points to CSV.

    *separator* delimits values, the default is comma.
    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional, for each point first its
    coordinate is converted to string (separated by *separator*), then each
    part of its value.
    """
    # Prepare output lines
    lines = []
    if header is not None:
        lines.append(str(header))

    # Determine how to iterate over points; support dict-like or arbitrary iterable
    try:
        points_iter = self.items()  # dict-style: (coord, value)
    except AttributeError:
        try:
            points_iter = iter(self)  # generic iterable
        except TypeError:
            raise TypeError("object is not iterable - cannot convert to CSV")

    for point in points_iter:
        # Support (coord, value) pair directly or single value
        if isinstance(point, tuple) and len(point) == 2:
            coord, value = point
        else:
            coord, value = point, None

        # Convert coordinate(s)
        if isinstance(coord, (str, bytes)):
            coord_parts = [str(coord)]
        else:
            try:
                coord_parts = [str(c) for c in coord]
            except TypeError:
                coord_parts = [str(coord)]

        # Convert value(s)
        if value is None:
            value_parts = []
        elif isinstance(value, (str, bytes)):
            value_parts = [str(value)]
        else:
            try:
                value_parts = [str(v) for v in value]
            except TypeError:
                value_parts = [str(value)]

        # Build line and add to output
        line_parts = coord_parts + value_parts
        lines.append(separator.join(line_parts))

    return "\n".join(lines)

