def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Expect an attribute like `<coord_name>_err` to hold error values.
    error_attr = f"{coord_name}_err"
    error_data = getattr(self, error_attr, None)
    if error_data is None:
        raise AttributeError(
            f"Attribute '{error_attr}' not found on {self.__class__.__name__}"
        )
    # `error_data` might be a list, tuple, or any iterable of error values.
    # We treat any non-zero/non-None value as an error.
    indices = []
    for i, err in enumerate(error_data):
        # Consider numpy.nan, None, or zero as non-error; everything else as error.
        if err is None:
            continue
        try:
            # For numeric types, zero is considered False.
            if err:
                indices.append(i)
        except Exception:
            # If comparison fails (e.g., an object), include it as an error.
            indices.append(i)
    return indices

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        import math
        # Locate the error dictionary
        err_dict = getattr(self, 'coord_err', None)
        if err_dict is None:  # fallback to a generic attribute name
            err_dict = getattr(self, 'err', None)
        if err_dict is None:
            raise AttributeError("No error information found in the object.")
        # If the coordinate is not present, return an empty list
        if coord_name not in err_dict:
            return []
        err = err_dict[coord_name]
        # Ensure the error container is iterable
        try:
            iter(err)
        except TypeError:
            return []
        indices = []
        for i, val in enumerate(err):
            # Skip missing or undefined errors
            if val is None:
                continue
            if isinstance(val, float) and math.isnan(val):
                continue
            # Skip zero errors if they are not meaningful
            if val == 0:
                continue
            indices.append(i)
        return indices

