def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """

    import copy

    # When level is 0 we do not recurse; we only compare top level.
    # When level < 0 we recurse indefinitely.
    # When level > 0 we decrement at each recursion until it becomes 0.

    def _diff(d1_dict, d2_dict, cur_level):
        result = {}
        for key, val1 in d1_dict.items():
            if key not in d2_dict:
                # missing key, include deep copy of value
                result[key] = copy.deepcopy(val1)
            else:
                val2 = d2_dict[key]
                # If values are equal, skip
                if val1 == val2:
                    continue
                # If both are dicts, recurse if allowed
                if isinstance(val1, dict) and isinstance(val2, dict):
                    if cur_level != 0:
                        sub_level = cur_level - 1 if cur_level > 0 else -1
                        subdiff = _diff(val1, val2, sub_level)
                        if subdiff:  # only include if non-empty
                            result[key] = subdiff
                else:
                    # values differ and not both dicts: include copy of val1
                    result[key] = copy.deepcopy(val1)
        return result

    # Ensure inputs are dicts; otherwise return empty dict
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return {}
    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    def _diff(a, b, l):
        diff = {}
        for key, val_a in a.items():
            if key not in b:
                diff[key] = val_a
                continue

            val_b = b[key]
            # Both values are dicts
            if isinstance(val_a, dict) and isinstance(val_b, dict):
                if l == -1 or l > 1:
                    sublevel = l - 1 if l > 0 else l
                    sub = _diff(val_a, val_b, sublevel)
                    if sub:
                        diff[key] = sub
                else:  # l == 1
                    if val_a != val_b:
                        diff[key] = val_a
                continue

            # values are different (or not both dicts)
            if val_a != val_b:
                diff[key] = val_a

        return diff

    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    def _diff(a, b, lev):
        res = {}
        for k, v in a.items():
            if k not in b:
                res[k] = v
                continue

            v2 = b[k]
            # Handle dictionary values
            if isinstance(v, dict) and isinstance(v2, dict):
                # Determine new level for recursion
                if lev == -1 or lev > 1:
                    sublev = -1 if lev == -1 else lev - 1
                    sub_res = _diff(v, v2, sublev)
                    if sub_res:
                        res[k] = sub_res
                else:
                    # level <= 1: compare values directly
                    if v != v2:
                        res[k] = v
            else:
                if v != v2:
                    res[k] = v
        return res

    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both arguments must be dictionaries")

    from copy import deepcopy

    if level == 0:
        return {}

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            result[key] = deepcopy(val1)
        else:
            val2 = d2[key]
            if isinstance(val1, dict) and isinstance(val2, dict):
                sublevel = level - 1 if level > 0 else -1
                subdiff = difference(val1, val2, sublevel)
                if subdiff:
                    result[key] = subdiff
            else:
                if val1 != val2 and (level == -1 or level >= 1):
                    result[key] = deepcopy(val1)
    return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Regular expressions for AWS-like tag keys and values.
    # Keys and values must be 1-256 characters and may contain alphanumerics,
    # spaces, periods, hyphens, and underscores.
    KEY_REGEX = re.compile(r'^[A-Za-z0-9_.-]{1,256}$')
    VALUE_REGEX = re.compile(r'^[A-Za-z0-9_.-]{0,256}$')

    errors = []

    if not isinstance(labels, dict):
        raise ValidationError([{'labels': 'Expected a dictionary of labels'}])

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            key_str = key.decode() if isinstance(key, bytes) else key
            if not KEY_REGEX.match(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex"})

        # Validate value(s)
        if isinstance(value, (list, tuple)):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    errors.append({str(v): 'expected string or bytes-like object'})
                else:
                    v_str = v.decode() if isinstance(v, bytes) else v
                    if not VALUE_REGEX.match(v_str):
                        errors.append({v_str: f"Label value '{v_str}' does not match the regex"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                v_str = value.decode() if isinstance(value, bytes) else value
                if not VALUE_REGEX.match(v_str):
                    errors.append({v_str: f"Label value '{v_str}' does not match the regex"})

    if errors:
        raise ValidationError(errors)

