def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a Kubernetes manifest dictionary.
    Non-list and non-dict leaf values are replaced with None.
    For the top-level dictionary (when first_level is True), identifying fields such as
    ``apiVersion``, ``kind``, and the ``metadata`` fields ``name`` and ``namespace`` are copied
    directly from the manifest.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): Indicates if this dictionary represents the whole
            observer_schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema
    """
    result = {}
    for key, value in manifest_dict.items():
        # Process nested dictionaries recursively
        if isinstance(value, dict):
            if first_level and key == "metadata":
                # For the top-level metadata we copy only name and namespace
                meta_copy = {}
                for subkey in ("name", "namespace"):
                    if subkey in value:
                        meta_copy[subkey] = value[subkey]
                result[key] = meta_copy
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        # Process lists: preserve list structure, recurse into dict items, replace scalars with None
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        # For scalar values, replace with None unless this is a top-level identifying field
        else:
            if first_level and key in ("apiVersion", "kind"):
                result[key] = value
            else:
                result[key] = None
    return result

