        # If the input is not a mapping, we simply return None.
        return None

    # Identify the keys that should preserve their original value when at the
    # top level of the schema. These usually refer to metadata that uniquely
    # identifies the resource.
    identifying_fields = {"metadata", "apiVersion", "kind"}

    def _process_dict(d: dict, top_level: bool):
        result = {}
        for key, value in d.items():
            if isinstance(value, dict):
                # Recurse into nested dictionaries. We keep ``top_level`` as
                # ``False`` for all deeper levels to avoid copying identifying
                # fields multiple times.
                result[key] = _process_dict(value, False)
            elif isinstance(value, list):
                result[key] = _process_list(value, False)
            else:
                # Leaf value; replace with ``None`` unless we are at the top
                # level and the key is an identifying field.
                if top_level and key in identifying_fields:
                    result[key] = value
                else:
                    result[key] = None
        return result

    def _process_list(l: list, top_level: bool):
        processed = []
        for item in l:
            if isinstance(item, dict):
                processed.append(_process_dict(item, top_level))
            elif isinstance(item, list):
                processed.append(_process_list(item, top_level))
            else:
                processed.append(None)
        return processed

    return _process_dict(manifest_dict, first_level)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Recursively fill missing fields in a list‑structured *last_applied_manifest*
    based on an observed schema and a partial Kubernetes API response.

    The function walks through each item of ``response`` and ensures that
    ``last_applied_manifest`` contains at least the same number of elements.
    For every field described in ``observer_schema`` the value from
    ``response`` is copied into ``last_applied_manifest`` if that field is
    missing.

    Args:
        last_applied_manifest (list): The list that is being updated.
        observer_schema (list | dict): The fields that should be present in
            each element.  When the schema is a list it is interpreted as a
            list of field names or a list of mapping objects that are used
            uniformly for every element.  When it is a mapping the keys
            specify the expected shape of the element.
        response (list): The partial response pulled from the Kubernetes API.
    """
    if not isinstance(response, list):
        # If the response is not a list, we consider it a sentinel that
        # simply replaces the missing part of the list.
        if len(last_applied_manifest) == 0:
            last_applied_manifest.extend(response)
        return

    # Ensure the destination is a list too.
    if not isinstance(last_applied_manifest, list):
        last_applied_manifest[:] = []

    # Standardise the schema for an individual element.
    def schema_for_index(idx):
        """Return a schema for the element at *idx*."""
        if isinstance(observer_schema, list):
            # Common case: a homogeneous list of field names or a uniform
            # mapping object that applies to all list items.
            if len(observer_schema) == 0:
                return None
            if isinstance(observer_schema[0], dict):
                return observer_schema[0]
            # Otherwise treat the whole list as a collection of field names.
            return set(observer_schema)
        if isinstance(observer_schema, dict):
            return observer_schema
        return None

    # Helper that updates a dict element based on its sub‑schema.
    def update_item(dest, src, sub_schema):
        if isinstance(sub_schema, dict):
            # Every key in the mapping is an observed field.
            for k, sub_sub in sub_schema.items():
                if k not in src:
                    continue
                if isinstance(sub_sub, (list, dict)):
                    # Nested structure – initialise if missing.
                    if k not in dest or dest[k] is None:
                        dest[k] = {} if isinstance(sub_sub, dict) else []
                    if isinstance(sub_sub, dict):
                        update_last_applied_manifest_dict_from_resp(
                            dest[k], sub_sub, src[k]
                        )
                    else:
                        update_last_applied_manifest_list_from_resp(
                            dest[k], sub_sub, src[k]
                        )
                else:
                    # Scalar value – copy only if absent.
                    if k not in dest:
                        dest[k] = src[k]
        else:
            # Assume *sub_schema* is a set of field names.
            for k in sub_schema:
                if k in src and k not in dest:
                    dest[k] = src[k]

    for idx, src_item in enumerate(response):
        # Extend the destination list if needed.
        while len(last_applied_manifest) <= idx:
            # If the corresponding source item is a dict we start with an
            # empty mapping, otherwise with None (scalar).
            last_applied_manifest.append({} if isinstance(src_item, dict) else None)

        dest_item = last_applied_manifest[idx]
        if isinstance(src_item, dict):
            if dest_item is None:
                dest_item = {}
                last_applied_manifest[idx] = dest_item
            sub_schema = schema_for_index(idx)
            update_item(dest_item, src_item, sub_schema)
        else:
            # Scalar value – we only set it if the destination slot is empty.
            if last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = src_item

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Collect any explicitly defined observer schemas in the application spec
    explicit_schemas = getattr(app.spec, "observer_schemas", [])
    explicit_keys = {
        (sch.get("name"), sch.get("namespace", None)) for sch in explicit_schemas
    }

    default_schemas = []
    for resource in getattr(app.spec, "manifest", []):
        metadata = resource.get("metadata", {})
        name = metadata.get("name")
        namespace = metadata.get("namespace")
        # Skip if a custom schema for this resource already exists
        if (name, namespace) in explicit_keys:
            continue
        # Construct a simple default observer schema entry
        default_schemas.append(
            {
                "name": name,
                "namespace": namespace,
                "kind": resource.get("kind"),
                "observer_schema": "default",
            }
        )
    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from a resource's name to a minimal default observer schema.
    """
    # Map the name of each manifest resource to its default schema
    default_schemas = {}

    # Existing custom observer schemas, if any
    existing_schemas = {}
    if hasattr(app.spec, "observer"):
        existing_schemas = getattr(app.spec.observer, "schemas", {})

    # Iterate over each resource defined in the application manifest
    for resource in getattr(app.spec, "manifest", []):
        meta = resource.get("metadata", {})
        name = meta.get("name")
        if not name:
            # Skip resources without a specified name
            continue

        # Skip resources that already have a custom observer schema
        if name in existing_schemas:
            continue

        api_version = resource.get("apiVersion", "")
        kind = resource.get("kind", "")
        namespace = meta.get("namespace", "default")

        # Construct a minimal default schema for the resource
        default_schemas[name] = {
            "apiVersion": api_version,
            "kind": kind,
            "meta": {
                "name": name,
                "namespace": namespace,
            },
            # The following defaults can be expanded or overridden by custom schemas
            "status": {
                "conditions": [],
                "observed_generation": None,
            },
        }

    # Optionally merge these defaults into the existing observer configuration
    if hasattr(app.spec, "observer"):
        if not hasattr(app.spec.observer, "schemas"):
            app.spec.observer.schemas = {}
        app.spec.observer.schemas.update(default_schemas)
    else:
        # If no observer config exists, create one with the defaults
        app.spec.observer = type("ObserverSpec", (object,), {"schemas": default_schemas})()

    return default_schemas

def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        """
        Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.
        """
        # Working with str internally – keep bytes until the end
        is_bytes = isinstance(sql, bytes)
        if is_bytes:
            sql_text = sql.decode("utf-8")
        else:
            sql_text = sql

        # Get in‑style and out‑style from the object (they should be strings
        # such as "named", "numeric", "qmark" or "format")
        in_style = getattr(self, "SQLParams", None).in_style  # type: ignore
        out_style = getattr(self, "SQLParams", None).out_style  # type: ignore

        # If styles are identical, return the input unchanged
        if in_style == out_style:
            return (sql, params)

        # Helper to generate an out‑placeholder for a given ordinal position
        def out_placeholder(pos: int) -> str:
            if out_style == "named":
                return f":p{pos}"
            if out_style == "numeric":
                return f":{pos}"
            if out_style == "qmark":
                return "?"
            if out_style == "format":
                return "%s"
            raise ValueError(f"Unsupported out_style: {out_style}")

        # Determine pattern and extractor based on the in_style
        if in_style == "named":
            # Placeholder :name
            pattern = re.compile(r":(?P<name>[A-Za-z0-9_]+)")
            # We capture names in the order they appear
            placeholder_names: List[str] = []

            def replace_named(match: re.Match[str]) -> str:
                name = match.group("name")
                placeholder_names.append(name)
                pos = len(placeholder_names)
                return out_placeholder(pos)

            new_sql = pattern.sub(replace_named, sql_text)

            # Build out_params: for named out_style a dict, else a list
            if out_style == "named":
                out_params = {f"p{idx}": params[name] for idx, name in enumerate(placeholder_names, start=1)}
            else:
                out_params = [params[name] for name in placeholder_names]

        elif in_style == "numeric":
            # Placeholder :1, :2, etc.
            pattern = re.compile(r":(?P<idx>[1-9][0-9]*)")
            placeholder_positions: List[int] = []

            def replace_numeric(match: re.Match[str]) -> str:
                idx = int(match.group("idx"))
                # For consistency we keep original numeric order, but we use
                # the position in the string to build the output list
                placeholder_positions.append(idx)
                pos = len(placeholder_positions)
                return out_placeholder(pos)

            new_sql = pattern.sub(replace_numeric, sql_text)

            # Build out_params
            if out_style == "named":
                out_params = {f"p{pos}": params[idx - 1] for pos, idx in enumerate(placeholder_positions, start=1)}
            else:
                out_params = [params[idx - 1] for idx in placeholder_positions]

        elif in_style == "qmark":
            # Placeholder '?'
            pattern = re.compile(r"\?")
            # Count occurrences; they map directly to the sequence order
            def replace_qmark(match: re.Match[str]) -> str:
                new_sql_list.append(out_placeholder(len(new_sql_list) + 1))
                return new_sql_list[-1]
            # We will collect rebuilt SQL pieces
            new_sql_parts: List[str] = []
            cursor = 0
            for m in pattern.finditer(sql_text):
                new_sql_parts.append(sql_text[cursor:m.start()])
                new_sql_parts.append(out_placeholder(len(new_sql_parts) + 1))
                cursor = m.end()
            new_sql_parts.append(sql_text[cursor:])
            new_sql = "".join(new_sql_parts)

            # Build out_params: it's just the sequence as is
            out_params = list(params)

        elif in_style == "format":
            # Placeholder '%s'
            pattern = re.compile(r"%s")
            def replace_format(match: re.Match[str]) -> str:
                new_sql_parts.append(out_placeholder(len(new_sql_parts) + 1))
                return new_sql_parts[-1]

            new_sql_parts: List[str] = []
            cursor = 0
            for m in pattern.finditer(sql_text):
                new_sql_parts.append(sql_text[cursor:m.start()])
                new_sql_parts.append(out_placeholder(len(new_sql_parts) + 1))
                cursor = m.end()
            new_sql_parts.append(sql_text[cursor:])
            new_sql = "".join(new_sql_parts)

            out_params = list(params)

        else:
            raise ValueError(f"Unsupported in_style: {in_style}")

        # Re‑encode to bytes if input was bytes
        if is_bytes:
            new_sql = new_sql.encode("utf-8")
        return (new_sql, out_params)

def formatmany(
        self,
        sql: AnyStr,
        many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
    ) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
        """Convert a list of in‑style parameter sets into out‑style."""
        # If no parameters supplied, return the original SQL and empty list
        try:
            iterator = iter(many_params)
        except TypeError:
            raise TypeError("many_params must be an iterable of mappings or sequences")
        out_sql: AnyStr | None = None
        out_params_list: List = []
        for params in iterator:
            # Use the single‑row format method (assumed to exist on this class)
            formatted_sql, out_params = self.format(sql, params)
            # Ensure that all rows use the same formatted SQL template
            if out_sql is None:
                out_sql = formatted_sql
            elif formatted_sql != out_sql:
                raise ValueError("inconsistent SQL across parameter sets")
            out_params_list.append(out_params)
        # If out_sql was never set (e.g. empty iterator), keep original sql
        if out_sql is None:
            out_sql = sql
        return out_sql, out_params_list.

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        # Prefer the library's built‑in validator if available.
        try:
            from ocfl.validation import validate_object
        except Exception:
            # If no validator is present, fall back to a very light check
            def validate_object(_):
                try:
                    import os
                    # Basic sanity check: path must exist and be a directory
                    if isinstance(_, str):
                        if not os.path.isdir(_):
                            return False
                        # Check for at least one file that typically exists
                        # in an OCFL object – a manifest file
                        return any(f.startswith('manifest-')
                                   for f in os.listdir(_))
                    else:
                        # Assume a pyfilesystem instance
                        return bool(_) and _.isdir('.') and any(f.startswith('manifest-')
                                                                 for f in _.listdir('.'))
                except Exception:
                    return False

        # Run the validator – it may raise exceptions on errors.
        try:
            result = validate_object(path)
            # If the validator returns a list/tuple, interpret emptiness
            if isinstance(result, (list, tuple)):
                # If there are errors, result may contain a flag
                # but we treat any non‑empty list as a failure for safety.
                return not result
            return bool(result)
        except Exception:
            return False

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        # Ensure we have a pyfs-like filesystem object
        fs = path if hasattr(path, "open") and hasattr(path, "exists") else None
        if not fs:
            try:
                # Assume pyfs is available in the environment
                fs = pyfs.open_fs(path)
            except Exception as exc:
                # If we cannot open the path, validation fails
                if not hasattr(self, "errors"):
                    self.errors = []
                self.errors.append(f"Cannot open path '{path}': {exc}")
                return False

        # Basic check for essential OCFL root files
        required_files = ["descriptor.json", ".ocfl_root.json"]
        optional_dir = "content"

        valid = True
        errors = []
        warnings = []

        # Verify required files exist
        for name in required_files:
            if not fs.exists(name):
                errors.append(f"Missing required file: {name}")
                valid = False

        # Verify required directory exists and is a directory
        if not fs.isdir(optional_dir):
            errors.append(f"Missing required directory: {optional_dir}")
            valid = False
        elif not fs.listdir(optional_dir):
            warnings.append(f"Directory '{optional_dir}' is empty")

        # Record errors and warnings
        if hasattr(self, "errors"):
            self.errors.extend(errors)
        else:
            self.errors = errors
        if hasattr(self, "warnings"):
            self.warnings.extend(warnings)
        else:
            self.warnings = warnings

        return valid

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Use only standard libraries; import locally inside the function
    import pathlib
    try:
        p = pathlib.Path(path)

        # Must be a directory
        if not p.is_dir():
            return False

        # Required components for a valid OCFL root
        required = [".ocfl_version", "metadata", "objects", "manifests"]
        for comp in required:
            comp_path = p / comp
            # Comp can be a file (.ocfl_version) or a directory
            if not comp_path.exists():
                return False

        # Validate that the .ocfl_version file is readable and not empty
        version_file = p / ".ocfl_version"
        if version_file.is_file():
            try:
                content = version_file.read_text(encoding="utf-8").strip()
                # Basic sanity check: version string should not be empty
                if not content:
                    return False
            except Exception:
                return False
        else:
            return False

        # If all checks passed, consider the object valid
        return True

    except Exception:
        # Any unexpected error results in validation failure
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # The object must be a directory
        if not getattr(path, "is_dir", lambda: False)():
            return False

        # Must contain the .ocfl-root marker file
        root_file = getattr(path, "joinpath", lambda p: None)(".ocfl-root")
        if root_file is None or not getattr(root_file, "is_file", lambda: False)():
            return False

        # Must have a content directory
        content_dir = getattr(path, "joinpath", lambda p: None)("content")
        if content_dir is None or not getattr(content_dir, "is_dir", lambda: False)():
            return False

        # Must have a versions directory
        versions_dir = getattr(path, "joinpath", lambda p: None)("versions")
        if versions_dir is None or not getattr(versions_dir, "is_dir", lambda: False)():
            return False

        # Ensure at least one version subdirectory exists
        has_version = False
        for child in getattr(versions_dir, "listdir", lambda: [])():
            if getattr(child, "is_dir", lambda: False)():
                has_version = True
                break
        if not has_version:
            return False

        return True
    except Exception:
        # Any unexpected error disqualifies the object
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    parts = []

    # If the validator exposes a boolean `is_valid` attribute,
    # include its obvious status.
    if hasattr(self, 'is_valid'):
        parts.append('Valid' if self.is_valid else 'Invalid')

    # Include the count of errors, if the validator keeps an
    # iterable `errors` attribute.
    if hasattr(self, 'errors'):
        try:
            err_count = len(self.errors)
            if err_count:
                parts.append(f"{err_count} error{'s' if err_count != 1 else ''}")
        except Exception:
            # `errors` is not a length‑aware iterable; ignore it.
            pass

    # Include the count of warnings, if the validator keeps an
    # iterable `warnings` attribute.
    if hasattr(self, 'warnings'):
        try:
            warn_count = len(self.warnings)
            if warn_count:
                parts.append(f"{warn_count} warning{'s' if warn_count != 1 else ''}")
        except Exception:
            # `warnings` is not a length‑aware iterable; ignore it.
            pass

    # Fallback in case nothing is available.
    if not parts:
        parts.append('No status information')

    return prefix + "; ".join(parts)

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        status = 'UNKNOWN'
    return f"{prefix}{status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to retrieve the log from common attribute names
    log = getattr(self, 'validation_log', None) or getattr(self, 'log', None) or []
    # Ensure we have an iterable
    if not isinstance(log, (list, tuple)):
        return ''
    lines = []
    for entry in log:
        if isinstance(entry, str):
            # simple string entry
            lines.append(f"{prefix}{entry}")
        elif isinstance(entry, (list, tuple)):
            # allow tuple like (level, message) or (msg, level)
            # try to format with level if possible
            try:
                level, msg = entry
                lines.append(f"{prefix}[{str(level).upper()}] {msg}")
            except Exception:
                # fallback for odd structures
                lines.append(f"{prefix}{str(entry)}")
        else:
            # fallback for any other type
            lines.append(f"{prefix}{str(entry)}")
    return "\n".join(lines)

def status_str(self, prefix=''):
        """Return string representation of validation log, with optional prefix."""
        # Try several common attribute names that might contain log entries.
        entries = getattr(self, 'entries', None)
        if entries is None:
            entries = getattr(self, 'log', [])
        # Ensure we are working with an iterable of strings.
        if not isinstance(entries, (list, tuple)):
            entries = [str(entries)]
        return '\n'.join(f'{prefix}{entry}' for entry in entries)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Retrieve the validation log; it may not exist or may be empty.
    log = getattr(self, 'validation_log', [])
    if not log:
        return ''
    # Build the output line by line, applying the optional prefix.
    lines = []
    for entry in log:
        # If the entry is a dict, use a 'message' key if available.
        if isinstance(entry, dict):
            msg = entry.get('message', str(entry))
        # If the entry is a tuple or list, use the first element as message.
        elif isinstance(entry, (tuple, list)) and entry:
            msg = entry[0]
        else:
            msg = entry
        lines.append(f"{prefix}{msg}")
    return "\n".join(lines)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Try to locate the log attribute
    log = getattr(self, 'log', None)
    if log is None:
        log = getattr(self, 'messages', getattr(self, 'log_entries', []))

    # If log is a dictionary, take its values
    if isinstance(log, dict):
        log = log.values()

    # If log is not iterable, just use its string representation
    if not hasattr(log, '__iter__'):
        log = [str(log)]

    # Build the prefixed string
    return '\n'.join(f"{prefix}{str(item)}" for item in log)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a dictionary")

    # Determine the spec version to use
    spec_version = getattr(self, "spec_version", None)
    if extract_spec_version:
        type_val = inventory.get("type")
        if type_val:
            # Try to extract a version number from the type string
            parts = str(type_val).split()
            for part in reversed(parts):
                cleaned = part.replace(".", "", 1)
                if cleaned.isdigit():
                    spec_version = part
                    break

    if spec_version is None:
        raise ValueError("Could not determine specification version")

    # Store the determined version on the instance (optional)
    self.spec_version = spec_version

    # Simple example checks based on the spec version
    allowed_versions = {"1.0", "2.0", "3.0"}
    if spec_version not in allowed_versions:
        raise ValueError(f"Unsupported specification version: {spec_version}")

    # Example required keys that must be present in the inventory
    required_keys = {"id", "name", "items"}
    missing_keys = required_keys - inventory.keys()
    if missing_keys:
        raise ValueError(f"Inventory missing required keys: {missing_keys}")

    # More complex validation logic would go here

    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure inventory is a dictionary
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a dict")

    # Determine the specification version
    spec_version = None
    if extract_spec_version:
        type_val = inventory.get('type')
        # Attempt to map the 'type' to a spec_version if such a mapping exists
        type_to_spec = getattr(self, 'type_to_spec_version', {})
        if isinstance(type_val, str):
            spec_version = type_to_spec.get(type_val.lower())
        # If mapping fails or no type present, fall back to the instance's spec_version
        if spec_version is None:
            spec_version = getattr(self, 'spec_version', None)
    else:
        spec_version = getattr(self, 'spec_version', None)

    if spec_version is None:
        raise ValueError("Unable to determine specification version for validation")

    # Basic required fields that every inventory should have
    basic_fields = ['name']
    for field in basic_fields:
        if field not in inventory:
            raise ValueError(f"inventory missing required field: '{field}'")
        if not isinstance(inventory[field], str):
            raise ValueError(f"'{field}' must be a string")

    # Example of spec_version-dependent checks
    # These can be expanded to match the actual spec
    version_aware_required = {
        '1.0': ['attributes', 'runs'],
        '2.0': ['metadata', 'attributes'],
    }

    required = version_aware_required.get(spec_version, ['attributes'])
    for field in required:
        if field not in inventory:
            raise ValueError(f"inventory missing required field for spec_version {spec_version}: '{field}'")

    # If all checks pass, return True
    return True

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Derive spec version from the type field if requested
    if extract_spec_version:
        inv_type = inventory.get("type")
        if isinstance(inv_type, str):
            # Very permissive heuristics: look for "v1" or "v2" in the type
            lower_type = inv_type.lower()
            if "v1" in lower_type:
                self.spec_version = "v1"
            elif "v2" in lower_type:
                self.spec_version = "v2"
            # If the type doesn't match known patterns we keep the existing
            # spec_version and simply do not raise here
    # If spec_version is still unset we cannot perform detailed validation
    spec_version = getattr(self, "spec_version", None)
    if not spec_version:
        return inventory

    # Validation rules per spec version
    validation_rules = {
        "v1": {"required": ["name", "description"]},
        "v2": {"required": ["name", "description", "configuration"]},
    }
    rules = validation_rules.get(spec_version)
    if rules:
        missing = [field for field in rules["required"] if field not in inventory]
        if missing:
            raise ValueError(
                f"Inventory missing required fields for spec '{spec_version}': {missing}"
            )
    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalize digests_used to a set for fast lookup
    if not isinstance(digests_used, set):
        digests_used = set(digests_used)

    missing_files = []
    for fname, digest in manifest_files.items():
        # Accept both string digests and digest dicts that might contain a 'digest' key
        if isinstance(digest, dict):
            digest_val = digest.get('digest') or digest.get('value')
        else:
            digest_val = digest

        if digest_val not in digests_used:
            missing_files.append(fname)

    if missing_files:
        raise RuntimeError(
            f"Missing required digests for files: {', '.join(missing_files)}"
        )

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Utility to collect digests per file
    def _build_mapping(files):
        mapping = {}
        if isinstance(files, dict):
            for file, digests in files.items():
                mapping[file] = set(digests or [])
        elif isinstance(files, list):
            for entry in files:
                # case 1: dict with 'file' and 'digests'
                if isinstance(entry, dict):
                    file = entry.get("file")
                    digests = entry.get("digests") or entry.get("digests_list") or entry.get("digests_set") or []
                    if file is not None:
                        mapping[file] = set(digests)
                # case 2: tuple (file, digests)
                elif isinstance(entry, tuple) and len(entry) >= 2:
                    file, digests = entry[0], entry[1]
                    mapping[file] = set(digests or [])
                # case 3: object with attributes
                else:
                    try:
                        file = getattr(entry, "file", None)
                        digests = getattr(entry, "digests", None) or getattr(entry, "digests_list", None) or getattr(entry, "digests_set", None) or []
                        if file is not None:
                            mapping[file] = set(digests)
                    except Exception:
                        continue
        return mapping

    file_to_digests = _build_mapping(manifest_files)

    # Now check digests used
    if isinstance(digests_used, dict):
        # mapping file -> digests used
        for file, used in digests_used.items():
            if file not in file_to_digests:
                raise ValueError(f"File '{file}' referenced in digests_used but not present in manifest")
            missing = set(used or []) - file_to_digests[file]
            if missing:
                raise ValueError(f"Digests {missing} used for file '{file}' are missing from the manifest")
    else:
        # digests_used is an iterable of digests
        all_manifest_digests = set()
        for digs in file_to_digests.values():
            all_manifest_digests.update(digs)
        missing = set(digests_used or []) - all_manifest_digests
        if missing:
            raise ValueError(f"Digests {missing} used but not present in any manifest entry")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Determine the set of digests that are present in the manifest.
    # `manifest_files` is assumed to be an iterable of objects or dicts that expose
    # a `digest` attribute or key.  We support both attribute access and
    # dictionary lookup for robustness.
    present = set()
    for m in manifest_files:
        if isinstance(m, dict):
            digest = m.get("digest")
        else:
            digest = getattr(m, "digest", None)
        if digest is None:
            raise ValueError(f"Manifest entry {m!r} has no digest")
        present.add(digest)

    missing = digests_used - present
    if missing:
        raise ValueError(f"Digests used but not present in manifest: {sorted(missing)}")

    unused = present - digests_used
    if unused:
        raise ValueError(f"Digests present in manifest but not used: {sorted(unused)}")
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""

        # collect all expected digests from the manifest
        expected_digests = set()
        for mf in manifest_files:
            # support dicts or objects having a digest / checksum attribute
            if isinstance(mf, dict):
                # try common keys that may hold the digest value
                for key in ('digest', 'checksum', 'hash'):
                    if key in mf and mf[key]:
                        expected_digests.add(mf[key])
                        break
            else:
                # object with attributes
                for attr in ('digest', 'checksum', 'hash'):
                    value = getattr(mf, attr, None)
                    if value:
                        expected_digests.add(value)
                        break

        # convert the used digest list to a set for fast set operations
        used_digests = set(digests_used)

        # determine which used digests are missing from the manifest
        missing = used_digests - expected_digests
        # determine which digests in the manifest are not used
        unused = expected_digests - used_digests

        # return a dictionary containing the results
        return {
            'missing': sorted(missing),
            'unused': sorted(unused),
        }

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is a InventoryValidator instance
    if not isinstance(prior, self.__class__):
        raise TypeError("prior must be an InventoryValidator instance")

    # Retrieve the inventory objects from both validators
    try:
        inv_self = getattr(self, "inventory")
        inv_prior = getattr(prior, "inventory")
    except AttributeError as e:
        raise AttributeError("Both InventoryValidator instances must expose an 'inventory' attribute") from e

    # Basic sanity: the two inventories must refer to the same item (by id or key)
    # Use 'id' attribute if present, otherwise fallback to comparison by other
    # attributes that uniquely identify the inventory (like 'name', 'path', etc.).
    def _get_key(inv):
        if hasattr(inv, "id"):
            return inv.id
        # fall back to a tuple of unique keys if defined
        unique = getattr(inv, "__unique_keys__", None)
        if unique is not None:
            return tuple(getattr(inv, k, None) for k in unique)
        # otherwise use all attributes except those related to versioning
        return tuple(sorted(
            (k, getattr(inv, k)) for k in dir(inv)
            if not k.startswith("_") and k not in ("version", "created_at", "updated_at")
        ))

    try:
        key_self = _get_key(inv_self)
        key_prior = _get_key(inv_prior)
    except Exception as e:
        raise ValueError("Unable to determine a unique key for inventory comparison") from e

    if key_self != key_prior:
        raise ValueError("Current and prior inventories refer to different objects")

    # Determine version numbers
    def _get_version(inv):
        if hasattr(inv, "version"):
            v = inv.version
        elif hasattr(inv, "created_at"):
            # if version not present, use timestamp ordering
            v = getattr(inv, "created_at", None)
        else:
            raise AttributeError("Inventory object lacks a 'version' or 'created_at' attribute")
        if v is None:
            raise ValueError("Inventory version information is missing")
        return v

    try:
        self_version = _get_version(inv_self)
        prior_version = _get_version(inv_prior)
    except Exception as e:
        raise ValueError("Unable to retrieve version information from inventories") from e

    # Compare the version information. If numbers, ensure prior_version < self_version.
    # If timestamps, ensure prior < self.
    if isinstance(self_version, (int, float)) and isinstance(prior_version, (int, float)):
        if prior_version >= self_version:
            raise ValueError("Prior inventory must have an older version number than current")
    else:
        # Assume we can compare via < for timestamps or other non-numeric types
        if not (prior_version < self_version):
            raise ValueError("Prior inventory must be older (by timestamp or comparable ordering) than current")

    # Finally, perform a deep consistency check between attributes that should be identical across versions.
    # We skip version-related fields to allow evolution.
    ignore_attrs = {"version", "created_at", "updated_at", "_creation_time", "_update_time"}
    attrs = {k for k in dir(inv_self) if not k.startswith("_") and k not in ignore_attrs}
    for attr in attrs:
        val_self = getattr(inv_self, attr, None)
        val_prior = getattr(inv_prior, attr, None)
        if val_self != val_prior:
            raise ValueError(f"Attribute '{attr}' differs between current and prior inventory objects")

    return True  # Validation succeeded

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is an InventoryValidator instance (same class as self)
        if not isinstance(prior, type(self)):
            raise TypeError("prior must be an InventoryValidator instance")

        # Helper to get a comparable date/epoch from an InventoryValidator
        def _get_date(obj):
            for attr in ("timestamp", "created", "creation_time", "last_update", "date"):
                if hasattr(obj, attr):
                    return getattr(obj, attr)
            raise AttributeError(f"inventory object {obj} lacks a recognised date attribute")

        # Get the date/time for self and prior
        try:
            self_date = _get_date(self)
            prior_date = _get_date(prior)
        except AttributeError as exc:
            raise ValueError(f"Invalid date information: {exc}") from exc

        # Check that prior is older than self
        if prior_date >= self_date:
            raise ValueError("prior inventory must be older than the current inventory")

        # Optional: ensure that the two inventories belong to the same source.
        # This can be validated via an inventory_id or similar identifier.
        # We'll try common attribute names.
        def _get_id(obj):
            for attr in ("inventory_id", "id", "source_id", "identifier"):
                if hasattr(obj, attr):
                    return getattr(obj, attr)
            return None

        self_id = _get_id(self)
        prior_id = _get_id(prior)

        if self_id is not None and prior_id is not None and self_id != prior_id:
            raise ValueError("inventory identifiers (source) do not match between current and prior inventories")

        # If all checks passed, just return silently or True
        return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an InventoryValidator instance
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same InventoryValidator class")

    # Access attributes that are assumed to exist and have sane types
    try:
        current_version = getattr(self, "version")
        prior_version = getattr(prior, "version")
        current_inventory = getattr(self, "inventory")
        prior_inventory = getattr(prior, "inventory")
    except AttributeError as exc:
        raise ValueError("Required attributes missing for validation") from exc

    # Basic sanity checks for versioning
    if current_version is None or prior_version is None:
        raise ValueError("Both inventories must have a defined version")
    if not isinstance(current_version, int) or not isinstance(prior_version, int):
        raise TypeError("Version attributes must be integers")
    if prior_version >= current_version:
        raise ValueError(
            f"The prior inventory version ({prior_version}) must be less than the current inventory version ({current_version})"
        )

    # Ensure that the prior inventory is a subset of the current one
    if not isinstance(current_inventory, dict) or not isinstance(prior_inventory, dict):
        raise TypeError("Inventory attributes must be dictionaries")
    if not set(prior_inventory).issubset(set(current_inventory)):
        raise ValueError(
            "Prior inventory contains items that are not present in the current inventory"
        )

    # If appropriate, we could compare more deeply within each item; for now a shallow subset check suffices
    return True  # Validation passed

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is the same type as self
        if not isinstance(prior, type(self)):
            raise TypeError(
                f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}"
            )

        # Required attributes
        for attr in ("version", "inventory"):
            if not hasattr(self, attr):
                raise AttributeError(f"self instance lacks required attribute '{attr}'")
            if not hasattr(prior, attr):
                raise AttributeError(f"prior instance lacks required attribute '{attr}'")

        # Version check: prior must be older than current
        if prior.version >= self.version:
            raise ValueError(
                f"prior inventory version ({prior.version}) must be less than current version ({self.version})"
            )

        # Inventory should be a dict (or at least a mapping)
        if not isinstance(self.inventory, dict) or not isinstance(prior.inventory, dict):
            raise TypeError("inventory attributes must be mappings (dict-like objects)")

        # Ensure that the prior inventory is a subset of the current inventory
        for key, prior_value in prior.inventory.items():
            if key not in self.inventory:
                raise ValueError(f"Key {key!r} present in prior inventory but missing in current inventory")
            cur_value = self.inventory[key]
            if cur_value != prior_value:
                raise ValueError(f"Value mismatch for key {key!r}: prior={prior_value!r}, current={cur_value!r}")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}
    for logical_path, ver_map in inventory.items():
        # Expect ver_map to be a mapping version -> list/set of files
        if isinstance(ver_map, dict):
            files = ver_map.get(version)
            if files:
                # Ensure the result is a set of files
                path_map[logical_path] = set(files)
    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for element in inventory.values():
        state = element.get("state")
        if not state:
            continue
        elem_version = state.get("version")
        if elem_version is None or elem_version > version:
            # Skip items from later versions; they may appear in duplicates but
            # we only need to include content files from the requested version and
            # earlier ones that might reference the same files.
            continue
        logical_path = state.get("logical_path") or element.get("logical_path")
        if logical_path is None:
            continue
        content_files = element.get("content_files", set())
        # Ensure we always deal with a set
        if not isinstance(content_files, set):
            content_files = set(content_files)
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set(content_files)
        else:
            logical_path_map[logical_path].update(content_files)
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to interpret a version key as an integer for ordering
    def _ver_num(v):
        if isinstance(v, int):
            return v
        if isinstance(v, str):
            # Accept plain integers or prefixed with a 'v'
            if v.lower().startswith('v') and v[1:].isdigit():
                return int(v[1:])
            if v.isdigit():
                return int(v)
        raise ValueError(f"Cannot interpret version key {v!r}")

    # Ensure inventory contains the state that maps versions -> logical paths
    if not isinstance(inventory, dict) or 'state' not in inventory:
        raise ValueError("Inventory must be a dict containing a 'state' key")

    state = inventory['state']

    # Determine the numeric target version
    try:
        target_num = _ver_num(version)
    except ValueError as exc:
        raise ValueError(f"Invalid target version {version!r}") from exc

    # Order versions by numeric value
    ordered_versions = sorted(state.keys(), key=_ver_num)

    # Prepare the mapping dictionary
    mapping = {}
    for ver_key in ordered_versions:
        ver_num = _ver_num(ver_key)
        # Skip older versions
        if ver_num < target_num:
            continue

        # For this version, accumulate logical->content hash mapping
        snap = state.get(ver_key, {})
        if not isinstance(snap, dict):
            continue

        for logical_path, data in snap.items():
            # Data may be a simple hash or a dict containing the hash
            content_hash = None
            if isinstance(data, dict):
                # Search for common keys holding the content hash
                for key in ("content", "content_file", "file", "content_hash", "hash"):
                    if key in data:
                        content_hash = data[key]
                        break
            else:
                content_hash = data

            if content_hash is None:
                continue

            if logical_path not in mapping:
                mapping[logical_path] = set()
            mapping[logical_path].add(content_hash)

    return mapping

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    # Normalize manifest_files to a set for efficient lookups.
    if not hasattr(manifest_files, "__contains__"):
        raise ValueError("manifest_files must be an iterable of file names")
    manifest_set = set(manifest_files)

    # Helper to validate a single fixity entry (a dict).
    def _validate_entry(entry):
        if not isinstance(entry, dict):
            raise ValueError(f"Each fixity entry must be a dict, got {type(entry).__name__}")

        # Define the allowed keys for a fixity entry.
        allowed_keys = {"algorithm", "value", "target"}
        entry_keys = set(entry.keys())

        # Check for missing keys.
        missing = allowed_keys - entry_keys
        if missing:
            raise ValueError(f"Fixity entry missing keys: {sorted(missing)}")

        # Check for unexpected keys.
        unexpected = entry_keys - allowed_keys
        if unexpected:
            raise ValueError(f"Fixity entry contains unexpected keys: {sorted(unexpected)}")

        target = entry.get("target")
        # Ensure the target is present in the manifest.
        if target not in manifest_set:
            raise ValueError(f"Fixity entry references unknown file: '{target}'")

    # If multiple entries are provided as a list/tuple, validate each.
    if isinstance(fixity, (list, tuple)):
        if not fixity:
            raise ValueError("Fixity list/tuple is empty")
        for idx, entry in enumerate(fixity):
            try:
                _validate_entry(entry)
            except ValueError as exc:
                raise ValueError(f"Error in fixity entry {idx}: {exc}") from None
    else:
        # Validate a single entry.
        _validate_entry(fixity)

    return True

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if "files" not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")
    if not isinstance(fixity["files"], list):
        raise ValueError("Fixity 'files' must be a list")

    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be an iterable of file identifiers")

    manifest_set = set(manifest_files)

    # Validate each entry in the fixity block
    for idx, entry in enumerate(fixity["files"], start=1):
        if not isinstance(entry, dict):
            raise ValueError(f"Item #{idx} in fixity 'files' must be a dict")

        # Each entry must have a 'path' key pointing to a file in the manifest
        if "path" not in entry:
            raise ValueError(f"Item #{idx} missing required 'path' field")
        path = entry["path"]

        if path not in manifest_set:
            raise ValueError(f"Fixity entry #{idx} references unknown file '{path}'")

        # Optional: ensure that no unexpected top-level keys appear
        allowed_keys = {"path", "hash", "checksum", "size", "checksum_method"}
        unexpected = set(entry) - allowed_keys
        if unexpected:
            raise ValueError(f"Item #{idx} contains unexpected keys: {sorted(unexpected)}")

    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        errors = []

        # expected keys
        required_keys = {"message", "checksum", "date", "files"}
        if not isinstance(fixity, dict):
            errors.append("Fixity block must be a dictionary")
            return errors

        missing_keys = required_keys - set(fixity.keys())
        if missing_keys:
            errors.append(f"Missing required keys in fixity block: {', '.join(sorted(missing_keys))}")

        # basic type checks for required keys
        if "message" in fixity and not isinstance(fixity["message"], str):
            errors.append("The 'message' field must be a string")
        if "checksum" in fixity and not isinstance(fixity["checksum"], str):
            errors.append("The 'checksum' field must be a string")
        if "date" in fixity and not isinstance(fixity["date"], str):
            errors.append("The 'date' field must be a string")

        # Validate files list
        files = fixity.get("files")
        if files is None:
            errors.append("'files' field is missing")
        elif not isinstance(files, list):
            errors.append("The 'files' field must be a list")
        else:
            for idx, entry in enumerate(files):
                if not isinstance(entry, dict):
                    errors.append(f"File entry at index {idx} is not a dictionary")
                    continue
                if "file" not in entry:
                    errors.append(f"File entry at index {idx} missing 'file' key")
                    continue
                if "hash" not in entry:
