    # The fixity block must contain a 'checksum' key
    if 'checksum' not in fixity:
        raise ValueError("The fixity block must contain a 'checksum' key.")
    checksum_entry = fixity['checksum']
    if not isinstance(checksum_entry, dict):
        raise ValueError("The 'checksum' entry must be a dictionary mapping file names to hash values.")
    # Ensure all referenced files exist in the manifest
    for file_name in checksum_entry:
        if file_name not in manifest_files:
            raise ValueError(f"File '{file_name}' referenced in fixity block but not present in the manifest.")
    # If all checks pass, return True
    return True

