def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo em análise

    Returns
    -------
    dict
        Dicionário contendo a chave 'type' com valor 'asset' ou 'rendition' e 
        a chave 'path' com o caminho do arquivo analisado.
    """
    import os

    # Define extensões típicas de ativos e rendições
    asset_exts = {'.xml', '.shp', '.geojson', '.kml', '.tif', '.tiff', '.json'}
    rendition_exts = {'.png', '.jpg', '.jpeg', '.gif', '.bmp', '.pdf', '.tiff'}

    ext = os.path.splitext(file_path)[1].lower()
    if ext in asset_exts:
        file_type = 'asset'
    elif ext in rendition_exts:
        file_type = 'rendition'
    else:
        # Fallback heurística: se a palavra "render" aparecer no nome, assume como rendição
        if 'render' in prefix.lower() or 'rend' in file_path.lower():
            file_type = 'rendition'
        else:
            file_type = 'asset'

    # Atualiza o dicionário global `packages` se existir, senão cria
    if 'packages' not in globals():
        globals()['packages'] = {}
    packages = globals()['packages']

    # Armazena informações do arquivo
    packages[prefix] = {'type': file_type, 'path': file_path}

    # Retorna um dict com as informações
    return {'prefix': prefix, 'type': file_type, 'path': file_path}

