def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    if issue is None:
        return None, None
    # Get text from XML element or direct string
    if hasattr(issue, 'text'):
        text = issue.text if issue.text is not None else ''
    else:
        text = str(issue)
    s = text.strip()
    if not s:
        return None, None

    num = None
    suppl = None

    # Detect leading numeric part (including ranges like 2-5)
    i = 0
    while i < len(s):
        ch = s[i]
        if ch.isdigit():
            i += 1
            if i < len(s) and s[i] == '-':
                # accept dash only if followed by a digit
                if i + 1 < len(s) and s[i + 1].isdigit():
                    i += 1
                    while i < len(s) and s[i].isdigit():
                        i += 1
        else:
            break

    if i > 0 and s[0].isdigit():
        num = s[:i]
        rest = s[i:].strip()
        suppl = rest if rest else None
    else:
        # No leading number, search for first number within the string
        pos = None
        for idx, ch in enumerate(s):
            if ch.isdigit():
                pos = idx
                break
        if pos is not None:
            j = pos
            while j < len(s) and s[j].isdigit():
                j += 1
            num = s[pos:j]
            # Remove the numeric part from the string to get supplement
            suppl_part = s[:pos] + s[j:]
            suppl = suppl_part.strip() if suppl_part.strip() else None

    # Helper to strip non-alphanumeric characters from start/end
    def _clean(x):
        start = 0
        end = len(x)
        while start < end and not x[start].isalnum():
            start += 1
        while end > start and not x[end - 1].isalnum():
            end -= 1
        return x[start:end] if start < end else ''

    if suppl:
        suppl = _clean(suppl).lower()

    return num, suppl

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _format(v, level):
        indent_str = '  ' * level
        if hasattr(v, 'pretty') and callable(v.pretty):
            return v.pretty(level, debug)
        if isinstance(v, dict):
            items = [f"{indent_str}  {repr(k)}: {_format(val, level+1)}" for k, val in sorted(v.items())]
            return "{\n" + ",\n".join(items) + f"\n{indent_str}" + "}"
        if isinstance(v, (list, tuple, set)):
            open_sym = '[' if isinstance(v, list) else '(' if isinstance(v, tuple) else '{'
            close_sym = ']' if isinstance(v, list) else ')' if isinstance(v, tuple) else '}'
            items = [f"{indent_str}  {_format(item, level+1)}" for item in v]
            return f"{open_sym}\n" + ",\n".join(items) + f"\n{indent_str}{close_sym}"
        return repr(v)

    indent_str = '  ' * indent
    lines = []
    if debug:
        lines.append(f"{indent_str}{self.__class__.__name__} (id={id(self)})")
    if hasattr(self, "__dict__") and self.__dict__:
        for key in sorted(self.__dict__):
            val = self.__dict__[key]
            val_repr = _format(val, indent + 1)
            lines.append(f"{indent_str}  {key} = {val_repr}")
    else:
        lines.append(f"{indent_str}{repr(self)}")
    return "\n".join(lines)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    prefix = ' ' * indent
    if hasattr(self, '__dict__'):
        attrs = self.__dict__
        if debug:
            lines = [prefix + f'{self.__class__.__name__} (id={hex(id(self))})']
            for k, v in attrs.items():
                if hasattr(v, 'pretty'):
                    lines.append(v.pretty(indent + 4, debug))
                else:
                    lines.append(' ' * (indent + 4) + f'{k} = {repr(v)}')
            return '\n'.join(lines)
        else:
            kvs = ', '.join(f'{k}={repr(v)}' for k, v in attrs.items())
            return f'{self.__class__.__name__}({kvs})'
    else:
        return prefix + repr(self)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    spacing = '    '

    def _format(obj, level):
        sp = spacing * level
        # If the object has its own pretty method, delegate to it
        if hasattr(obj, 'pretty') and callable(obj.pretty) and obj is not self:
            return obj.pretty(level, debug)
        # Handle dictionaries
        if isinstance(obj, dict):
            lines = [f"{sp}{{"]
            for k, v in obj.items():
                lines.append(f"{sp}    {repr(k)}:")
                lines.extend(_format(v, level + 2).splitlines())
            lines.append(f"{sp}}}")
            return '\n'.join(lines)
        # Handle lists, tuples, sets
        if isinstance(obj, (list, tuple, set)):
            type_name = type(obj).__name__
            lines = [f"{sp}{type_name}("]
            for item in obj:
                lines.extend(_format(item, level + 2).splitlines())
            lines.append(f"{sp})")
            return '\n'.join(lines)
        # Default representation
        if debug:
            return f"{sp}{repr(obj)} ({type(obj).__name__})"
        else:
            return f"{sp}{repr(obj)}"

    top = spacing * indent
    lines = [f"{top}{self.__class__.__name__}:"]
    for name, value in vars(self).items():
        lines.append(f"{top}    {name}:")
        lines.append(_format(value, indent + 2))
    return '\n'.join(lines)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _format(obj, level):
        prefix = "    " * level
        # Avoid infinite recursion on self
        if obj is self:
            return prefix + repr(obj)
        # If the object has its own pretty method, use it
        if hasattr(obj, "pretty") and callable(obj.pretty):
            return obj.pretty(level, debug)
        # Format containers
        if isinstance(obj, dict):
            lines = [prefix + "{"]
            for k, v in obj.items():
                lines.append(f"{prefix}    {repr(k)}: {_format(v, level + 1)}")
            lines.append(prefix + "}")
            return "\n".join(lines)
        if isinstance(obj, (list, tuple, set)):
            if isinstance(obj, list):
                opening, closing = "[", "]"
            elif isinstance(obj, tuple):
                opening, closing = "(", ")"
            else:
                opening, closing = "{", "}"
            lines = [prefix + opening]
            for item in obj:
                lines.append(_format(item, level + 1))
            lines.append(prefix + closing)
            return "\n".join(lines)
        # Base case: simple objects
        return prefix + repr(obj)

    return _format(self, indent)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper functions (expects And, Or, Not classes with `args`/`arg` attributes)
    def is_subexpr(sub, expr):
        if sub == expr:
            return True
        if hasattr(expr, "args"):
            return any(is_subexpr(sub, a) for a in expr.args)
        if hasattr(expr, "arg"):
            return is_subexpr(sub, expr.arg)
        return False

    def simplify(expr):
        if hasattr(expr, "args"):  # generic handling for And/Or
            new_args = [simplify(a) for a in expr.args]
            # Try to reduce using absorption rules
            for a in new_args:
                for b in new_args:
                    if a is b:
                        continue
                    # Absorption: A & (A | B) = A
                    if isinstance(expr, And) and isinstance(b, Or) and is_subexpr(a, b):
                        return a
                    # Absorption: A | (A & B) = A
                    if isinstance(expr, Or) and isinstance(b, And) and is_subexpr(a, b):
                        return a
                    # Negative absorption: A & (~A | B) = A & B
                    if isinstance(expr, And) and isinstance(b, Or):
                        not_a = None
                        rest = None
                        for part in b.args:
                            if isinstance(part, Not) and part.arg == a:
                                not_a = part
                            else:
                                rest = part
                        if not_a is not None and rest is not None:
                            return And(a, rest)
                    # Negative absorption: A | (~A & B) = A | B
                    if isinstance(expr, Or) and isinstance(b, And):
                        not_a = None
                        rest = None
                        for part in b.args:
                            if isinstance(part, Not) and part.arg == a:
                                not_a = part
                            else:
                                rest = part
                        if not_a is not None and rest is not None:
                            return Or(a, rest)
            return type(expr)(*new_args)
        return expr

    # Simplify each argument and remove duplicates
    simplified = [simplify(a) for a in args]
    result = []
    seen = set()
    for a in simplified:
        # Using a difficult to hash expression; we skip dedupe if unhashable
        try:
            key = hash(a)
        except Exception:
            key = None
        if key is not None:
            if key in seen:
                continue
            seen.add(key)
        result.append(a)
    return result

