def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings.  The returned function always yields a ``bytes`` object
    regardless of the Python version.
    """
    import sys

    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] == 3:
            return result if isinstance(result, bytes) else result.encode('utf-8')
        # Python 2: ``str`` is bytes, ``unicode`` needs encoding
        return result if isinstance(result, str) else result.encode('utf-8')

    return wrapper

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if sys.version_info[0] >= 3:
        return namefunc
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if isinstance(result, unicode):
            return result.encode('utf-8')
        return result
    return wrapper

