    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        try:
            # In Python 2, 'unicode' is the string type
            if isinstance(result, unicode):
                return result.encode('utf-8')
        except NameError:
            # In Python 3, 'unicode' is not defined; nothing to adjust
            pass
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    import subprocess
    try:
        rev = subprocess.check_output(
            ['git', 'rev-parse', 'HEAD'],
            stderr=subprocess.DEVNULL
        ).decode('utf-8', errors='ignore').strip()
        tag = subprocess.check_output(
            ['git', 'describe', '--tags', '--always', '--dirty'],
            stderr=subprocess.DEVNULL
        ).decode('utf-8', errors='ignore').strip()
        return {"full-revisionid": rev, "version": tag}
    except Exception:
        return {"full-revisionid": "unknown", "version": "0.0.0"}

def get_versions():
    """Get version information or return default if unable to do so."""
    # Determine the correct package name (first component of the module or package).
    package_name = __package__ or __name__.split('.')[0]
    # Attempt to retrieve the package metadata via importlib.metadata (Python 3.8+).
    try:
        from importlib.metadata import version as _pkg_version
        return _pkg_version(package_name)
    except Exception:
        # Fallback to pkg_resources for older Python environments.
        try:
            import pkg_resources
            return pkg_resources.get_distribution(package_name).version
        except Exception:
            # Return a sane default if all attempts fail.
            return "0.0.0"

