def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Normalise pieces to a list
    try:
        seq = list(pieces)
    except Exception:
        return ""

    # Determine major, minor, patch, pre-release, and build components
    major = str(seq[0]) if len(seq) > 0 else None
    minor = str(seq[1]) if len(seq) > 1 else None
    patch = str(seq[2]) if len(seq) > 2 else None
    pre_release = str(seq[3]) if len(seq) > 3 else None
    build = str(seq[4]) if len(seq) > 4 else None

    # Decide whether we are rendering a short (numeric) or full (including
    # prerelease and build metadata) representation.
    short_flag = True
    if style is None:
        short_flag = True
    elif isinstance(style, int):
        # 0 -> short, 1 -> full
        short_flag = (style == 0)
    elif isinstance(style, str):
        lower = style.lower()
        if lower in {"full", "canonical", "semver", "verbose", "standard"}:
            short_flag = False
        elif lower in {"short", "basic", "compact", "tiny"}:
            short_flag = True
        else:
            # Default: short
            short_flag = True
    else:
        # Unknown style, default to short
        short_flag = True

    # Build numeric part
    numeric_parts = []
    if major is not None:
        numeric_parts.append(major)
    if minor is not None:
        numeric_parts.append(minor)
    if patch is not None:
        numeric_parts.append(patch)

    numeric_str = ".".join(numeric_parts)

    if short_flag:
        return numeric_str

    # Build full semver string
    result = numeric_str
    if pre_release:
        result += "-" + pre_release
    if build:
        result += "+" + build
    return result

