def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    seen = set()
    num_objects = 0
    good_objects = 0

    def _validate(obj):
        nonlocal num_objects, good_objects
        oid = id(obj)
        if oid in seen:
            return
        seen.add(oid)
        num_objects += 1
        ok = True

        # Object level validation
        if validate_objects and hasattr(obj, "validate"):
            try:
                ok = bool(obj.validate())
            except Exception as exc:
                ok = False
                if show_warnings:
                    print(f"Warning: validation failed for {obj!r} ({exc!s})")

        # Digest check
        if ok and check_digests and hasattr(obj, "digest") and hasattr(obj, "calculate_digest"):
            try:
                if obj.calculate_digest() != obj.digest:
                    ok = False
                    if show_warnings:
                        print(f"Warning: digest mismatch for {obj!r}")
            except Exception as exc:
                ok = False
                if show_warnings:
                    print(f"Warning: digest check error for {obj!r} ({exc!s})")

        if ok:
            good_objects += 1

        # Recurse into possible children
        children = None
        if hasattr(obj, "children"):
            children = getattr(obj, "children")
        elif hasattr(obj, "sub_objects"):
            children = getattr(obj, "sub_objects")
        elif hasattr(obj, "items"):
            # Might be a mapping of sub-objects
            items = getattr(obj, "items")
            try:
                children = items()
            except Exception:
                pass
        if children and isinstance(children, (list, tuple, set)):
            for child in children:
                _validate(child)

    # Identify root objects to start from
    roots = getattr(self, "objects", None)
    if roots is None:
        roots = getattr(self, "root_objects", None)
    if roots is None:
        roots = getattr(self, "items", None)
    if roots is None:
        roots = []
    # Normalize to iterable
    if isinstance(roots, dict):
        roots = list(roots.values())
    if not isinstance(roots, (list, tuple, set)):
        roots = [roots]

    for root in roots:
        _validate(root)

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        import os
        import hashlib

        # Determine the root directory to walk; fall back to the current path if not set
        root_dir = getattr(self, 'storage_root', getattr(self, 'root', '.'))

        num_objects = 0
        good_objects = 0

        for dirpath, _, files in os.walk(root_dir):
            for fname in files:
                full_path = os.path.join(dirpath, fname)
                num_objects += 1
                is_valid = True

                # Validate the object itself if requested
                if validate_objects:
                    try:
                        # Example placeholder validation: file must not be empty
                        if os.path.getsize(full_path) == 0:
                            is_valid = False
                    except Exception:
                        is_valid = False

                # Check digests if requested
                if check_digests:
                    try:
                        # Compute SHA256 of the file
                        hasher = hashlib.sha256()
                        with open(full_path, 'rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                hasher.update(chunk)
                        file_digest = hasher.hexdigest()

                        # Assume a companion .sha256 file contains the expected digest
                        digest_path = full_path + '.sha256'
                        if os.path.isfile(digest_path):
                            with open(digest_path, 'r', encoding='utf-8') as dg:
                                expected_digest = dg.read().strip()
                            if file_digest != expected_digest:
                                is_valid = False
                                if show_warnings:
                                    print(f'Digest mismatch for {full_path}')
                    except Exception:
                        is_valid = False

                if is_valid:
                    good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Retrieve objects from the object store
    objects = []
    try:
