            objects = self.list_objects()
        elif hasattr(self, 'objects'):
            objects = getattr(self, 'objects')
        elif hasattr(self, 'storage') and isinstance(self.storage, dict):
            objects = list(self.storage.values())
    except Exception:
        objects = []

    num_objects = len(objects)
    good_objects = 0

    for obj in objects:
        valid = True

        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    valid = bool(obj.validate())
                else:
                    valid = bool(getattr(obj, 'is_valid', True))
            except Exception as e:
                valid = False
                if show_warnings:
                    name = getattr(obj, 'name', str(obj))
                    print(f"Warning: validation of object {name} failed: {e}")

        if check_digests and valid:
            try:
                if hasattr(obj, 'digest') and hasattr(obj, 'expected_digest'):
                    valid = (obj.digest == obj.expected_digest)
                elif hasattr(obj, 'compute_digest'):
                    expected = getattr(obj, 'expected_digest', None)
                    if expected is not None:
                        valid = (obj.compute_digest() == expected)
            except Exception as e:
                valid = False
                if show_warnings:
                    name = getattr(obj, 'name', str(obj))
                    print(f"Warning: digest check failed for object {name}: {e}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        Parameters
        ----------
        validate_objects : bool, optional
            If True, perform internal validation checks on each object in the hierarchy.
        check_digests : bool, optional
            If True, verify that stored digests match computed digests for each object.
        show_warnings : bool, optional
            If True, output any warning messages encountered during validation to the console.

        Returns
        -------
        tuple
            (num_objects, good_objects)
            - num_objects : int
                Total number of objects checked.
            - good_objects : int
                Number of objects that passed all enabled validation checks.
        """
        # Assume the instance provides an iterable of objects representing the hierarchy.
        # It can be any attribute that yields the objects or a method that returns them.
        # Common patterns:
        #   - self.get_all_objects()
        #   - self.objects
        #   - self._storage_objects
        # Try to retrieve the collection in a flexible manner.
        objects = []
        candidate_attrs = ['get_all_objects', 'objects', 'all_objects', 'objects_list', '_objects']
        for attr in candidate_attrs:
            if hasattr(self, attr):
                val = getattr(self, attr)
                # If it's a method, call it; otherwise iterate directly.
                try:
                    if callable(val):
                        objects = list(val())
                    else:
                        objects = list(val)
                    break
                except Exception:
                    continue
        # If still empty, fall back to an empty list (nothing to validate)
        if not objects:
            return 0, 0

        num_objects = 0
        good_objects = 0

        for obj in objects:
            num_objects += 1
            is_valid = True
            # Validate internal consistency if requested
            if validate_objects:
                # If the object provides a validate() or is_valid attribute
                try:
                    if hasattr(obj, 'validate') and callable(obj.validate):
                        is_valid = obj.validate()
                    elif hasattr(obj, 'is_valid'):
                        is_valid = bool(obj.is_valid)
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[Warning] Validation failed for object {obj}: {exc}")

            # Check digest if requested
            if is_valid and check_digests:
                try:
                    # Assume obj has stored_digest and a method to compute the expected digest
                    stored = getattr(obj, 'stored_digest', None)
                    if stored is None:
                        # If no stored digest, skip checking
                        pass
                    else:
                        # Compute digest if possible
                        if hasattr(obj, 'compute_digest') and callable(obj.compute_digest):
                            computed = obj.compute_digest()
                        elif hasattr(obj, 'digest'):
                            computed = obj.digest
                        else:
                            computed = None

                        if computed != stored:
                            is_valid = False
                            if show_warnings:
                                print(f"[Warning] Digest mismatch for object {obj}. "
                                      f"Expected {computed}, stored {stored}")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"[Warning] Digest check failed for object {obj}: {exc}")

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Root inventory should already be loaded on the instance
        if not hasattr(self, "inventory") or self.inventory is None:
            raise AssertionError("Root inventory not set on the instance.")
        root_inventory = self.inventory

        cumulative_inventory = {}
        mismatches = []

        for vdir in version_dirs:
            # Locate the inventory file inside the version directory
            inv_path = os.path.join(vdir, "inventory.json")
            try:
                with open(inv_path, "r", encoding="utf-8") as fp:
                    current_inventory = json.load(fp)
            except Exception as e:
                raise AssertionError(f"Could not load inventory from '{inv_path}': {e}")

            if not isinstance(current_inventory, dict):
                raise AssertionError(f"Inventory in '{inv_path}' is not a dict.")

            # Ensure that every entry from the cumulative inventory exists in the current one
            for key, digest in cumulative_inventory.items():
                if key not in current_inventory:
                    raise AssertionError(
                        f"Missing content '{key}' in inventory of '{vdir}'. "
                        f"Expected at least as many items as previous versions."
                    )
                if current_inventory[key] != digest:
                    raise AssertionError(
                        f"Digest for '{key}' changed between versions "
                        f"({digest} -> {current_inventory[key]}) in '{vdir}'."
                    )

            # Update cumulative inventory to the latest data
            cumulative_inventory = current_inventory.copy()

            # Record any digest differences from the root inventory
            for key, digest in current_inventory.items():
                if key not in root_inventory:
                    continue
                root_digest = root_inventory[key]
                if digest != root_digest:
                    mismatches.append(
                        (
                            key,
                            vdir,
                            root_digest,
                            digest,
                        )
                    )

        # Store mismatches for later validation steps
        self.digest_mismatches = mismatches
        return None

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        if not os.path.exists(path):
            return f'Not found: {path}'
        if os.path.isfile(path):
            return 'file'
        if os.path.isdir(path):
            # Find Namaste files
            try:
                entries = os.listdir(path)
            except PermissionError:
                return f'Permission denied: {path}'
            namaste_files = [f for f in entries if f.startswith('0=')]
            if not namaste_files:
                return f'No Namaste file in {path}'
            # Heuristic: if a directory named 'objects' exists, it's a repo root
            if 'objects' in os.listdir(path):
                return 'root'
            # Heuristic: if directory contains 'versions' or 'inventory', it's an object
            if 'versions' in entries or 'inventory' in entries or 'content' in entries:
                return 'object'
            # Fallback: if only Namaste file present, try to infer from parent
            parent = os.path.dirname(path.rstrip(os.sep))
            if os.path.isdir(parent):
                if 'objects' in os.listdir(parent):
                    return 'root'
            return f'Unknown directory type: {path}'
        return f'Unsupported path type: {path}'
    except Exception as e:
        return f'Error: {e}'

