    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if not bug_ids:
        return params

    # Build a list of bug id strings
    if isinstance(bug_ids, (list, tuple, set)):
        ids_to_add = [str(bid) for bid in bug_ids if bid is not None]
    else:
        ids_to_add = [str(bug_ids)]

    # Merge with existing 'ids' if present
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            existing_ids = [part.strip() for part in existing.split(',') if part.strip()]
        else:
            existing_ids = [str(part) for part in existing if part is not None]
        ids_set = set(existing_ids) | set(ids_to_add)
    else:
        ids_set = set(ids_to_add)

    # Store as comma separated string
    params['ids'] = ",".join(sorted(ids_set, key=lambda x: int(x) if x.isdigit() else x))
