    # Helper to convert a MappingNode's value list into a dict keyed by key string
    def mapping_to_dict(mapping):
        """Return a dict mapping key string to (key_node, value_node)."""
        return {key_node.value: (key_node, value_node) for key_node, value_node in mapping.value}

    # Helper to merge two mapping value lists (in-place merging into `dest`)
    def merge_mapping_values(dest_mapping, src_mapping):
        """Merge src_mapping into dest_mapping recursively."""
        dest_dict = mapping_to_dict(dest_mapping)
        src_dict = mapping_to_dict(src_mapping)

        for key, (src_key_node, src_val_node) in src_dict.items():
            if key in dest_dict:
                dest_key_node, dest_val_node = dest_dict[key]
                # If both values are mappings, merge deeply
                if hasattr(dest_val_node, 'value') and hasattr(src_val_node, 'value'):
                    merge_mapping_values(dest_val_node, src_val_node)
                else:
                    # Replace with src (last wins)
                    dest_dict[key] = (src_key_node, src_val_node)
            else:
                # New key, add to dest_dict
                dest_dict[key] = (src_key_node, src_val_node)

        # Reconstruct the order: keep original dest order, then new keys
        new_value = []
        # Keep original dest keys in order
        for key_node, val_node in dest_mapping.value:
            key = key_node.value
            if key in dest_dict:
                new_value.append(dest_dict[key])
                del dest_dict[key]  # Mark as processed
        # Append any remaining new keys (those added from src that were not in dest)
        for key in dest_dict:
            new_value.append(dest_dict[key])

        # Update dest_mapping's value list
        dest_mapping.value = new_value

    # Main logic: iterate through nodes, merging duplicates
    merged = {}
    order = []  # Keep order of first occurrence of each key

    for key_node, val_node in nodes:
        key = key_node.value
        if key in merged:
            existing_key_node, existing_val_node = merged[key]
            # If both values are mappings, merge deeply
            if getattr(existing_val_node, 'value', None) is not None and \
               getattr(val_node, 'value', None) is not None:
                merge_mapping_values(existing_val_node, val_node)
            else:
                # Replace with new value (last wins)
                merged[key] = (key_node, val_node)
        else:
            merged[key] = (key_node, val_node)
