                mapping[k] = (existing_k_node, merged_value)
            else:
                mapping[k] = (k_node, v_node)
                order.append(k)
        # Reconstruct list preserving order
        merged_pairs = [(mapping[k][0], mapping[k][1]) for k in order]
        return MappingNode(tag=m1.tag, value=merged_pairs, start_mark=m1.start_mark, end_mark=m1.end_mark)

    # Main processing
    merged = {}
    key_order = []
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, value_node)
            key_order.append(key)
        else:
            existing_key_node, existing_value = merged[key]
            if isinstance(existing_value, MappingNode) and isinstance(value_node, MappingNode):
                new_value = merge_mapping_nodes(existing_value, value_node)
            else:
                new_value = value_node
            merged[key] = (existing_key_node, new_value)

    result = [(merged[k][0], merged[k][1]) for k in key_order]
    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def merge_mapping_nodes(node1, node2):
        # Merge two MappingNode instances (assuming both are MappingNodes)
        # Preserve the ordering of node1 and append any new keys from node2.
        mapping = {}
        order = []

        # Build initial mapping from node1
        for k_node, v_node in node1.value:
            key = k_node.value
            mapping[key] = (k_node, v_node)
            order.append(key)

        # Merge entries from node2
        for k_node, v_node in node2.value:
            key = k_node.value
            if key in mapping:
                existing_k_node, existing_v_node = mapping[key]
                if isinstance(existing_v_node, type(node2)) and isinstance(v_node, type(node2)):
                    # Recursively merge nested MappingNodes
                    merged_v = merge_mapping_nodes(existing_v_node, v_node)
                    mapping[key] = (existing_k_node, merged_v)
                else:
                    # Non-mapping values: override with the new one
                    mapping[key] = (existing_k_node, v_node)
            else:
                mapping[key] = (k_node, v_node)
                order.append(key)

        # Reconstruct the list preserving order
        merged_list = [mapping[k] for k in order]
        return type(node1)(tag=node1.tag, value=merged_list)

    merged_map = {}
    order = []

    for key_scalar, value in nodes:
        key_val = key_scalar.value
        if key_val in merged_map:
            existing_scalar, existing_value = merged_map[key_val]
            if isinstance(existing_value, type(value)) and isinstance(value, type(value)):
                # Both are MappingNodes, perform deep merge
                merged_value = merge_mapping_nodes(existing_value, value)
                merged_map[key_val] = (existing_scalar, merged_value)
            else:
                # Non-mapping values: last one wins
                merged_map[key_val] = (existing_scalar, value)
        else:
            merged_map[key_val] = (key_scalar, value)
            order.append(key_val)

    return [(merged_map[k][0], merged_map[k][1]) for k in order]

