def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
        parsed[name] = namespace
        unknown_sets.append(set(unknown))

    if unknown_sets:
        # arguments that were not recognized by any subparser
        remaining = sorted(set.intersection(*unknown_sets))
    else:
        remaining = []

    return parsed, remaining

def deep_merge_nodes(nodes):
    """
    Merge a list of (key_node, value_node) tuples by deeply merging mapping values
    for duplicate keys. The last occurrence of a non-mapping value wins.
    """
    # Helper to determine if a node represents a YAML mapping
    def is_mapping(node):
        return getattr(node, "tag", None) == "tag:yaml.org,2002:map" and hasattr(node, "value") and isinstance(node.value, list)

    # Recursively merge two mapping nodes
    def merge_mapping(m1, m2):
        dict1 = {pair[0].value: (pair[0], pair[1]) for pair in m1.value}
        dict2 = {pair[0].value: (pair[0], pair[1]) for pair in m2.value}
        merged_pairs = []
        for key in dict1.keys() | dict2.keys():
            if key in dict1 and key in dict2:
                key_node, val1 = dict1[key]
                _, val2 = dict2[key]
                merged_val = merge_values(val1, val2)
                merged_pairs.append((key_node, merged_val))
            elif key in dict1:
                merged_pairs.append(dict1[key])
            else:
                merged_pairs.append(dict2[key])
        return type(m1)(tag=m1.tag, value=merged_pairs)

    # Merge two value nodes according to the rules
    def merge_values(v1, v2):
        if is_mapping(v1) and is_mapping(v2):
            return merge_mapping(v1, v2)
        return v2

    merged_dict = {}
    key_order = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = (key_node, value_node)
            key_order.append(key)
        else:
            _, existing_value = merged_dict[key]
            merged_value = merge_values(existing_value, value_node)
            merged_dict[key] = (merged_dict[key][0], merged_value)

    return [(merged_dict[k][0], merged_dict[k][1]) for k in key_order]

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """

    def _merge_mapping_nodes(node1, node2):
        """
        Merge two ruamel.yaml.nodes.MappingNode objects recursively, returning a new MappingNode.
        """
        # Gather mapping from key-id to (key_node, value_node), preserving insertion order
        merged_map = {}

        # Helper to process a MappingNode's value list
        for k_node, v_node in node1.value:
            key_id = (k_node.tag, k_node.value)
            merged_map[key_id] = (k_node, v_node)

        for k_node, v_node in node2.value:
            key_id = (k_node.tag, k_node.value)
            if key_id in merged_map:
                existing_key, existing_val = merged_map[key_id]
                if isinstance(existing_val, MappingNode) and isinstance(v_node, MappingNode):
                    # Recursive merge
                    merged_val = _merge_mapping_nodes(existing_val, v_node)
                    merged_map[key_id] = (existing_key, merged_val)
                else:
                    # Override with node2's key and value
                    merged_map[key_id] = (k_node, v_node)
            else:
                merged_map[key_id] = (k_node, v_node)

        # Build a new MappingNode, keeping flow style from node1 if present
        merged_value = list(merged_map.values())
        flow_style = getattr(node1, "flow_style", None)
        return MappingNode(tag=node1.tag, value=merged_value, flow_style=flow_style)

    result_map = {}
    for key_node, val_node in nodes:
        key_id = (key_node.tag, key_node.value)
        if key_id in result_map:
            existing_key, existing_val = result_map[key_id]
            if isinstance(existing_val, MappingNode) and isinstance(val_node, MappingNode):
                merged_val = _merge_mapping_nodes(existing_val, val_node)
                result_map[key_id] = (key_node, merged_val)
            else:
                result_map[key_id] = (key_node, val_node)
        else:
            result_map[key_id] = (key_node, val_node)

    return list(result_map.values())

def deep_merge_nodes(nodes):
    """
    Merge nodes that share the same key, deep‑merging mapping values.
    """
    def merge_mapping_nodes(m1, m2):
        """Merge two MappingNode objects."""
        merged_items = []
        index_map = {}
        for k_node, v_node in m1.value:
            k = k_node.value
            index_map[k] = len(merged_items)
            merged_items.append((k_node, v_node))
        for k_node, v_node in m2.value:
            k = k_node.value
            if k in index_map:
                idx = index_map[k]
                old_key_node, old_val_node = merged_items[idx]
                if isinstance(old_val_node, MappingNode) and isinstance(v_node, MappingNode):
                    merged = merge_mapping_nodes(old_val_node, v_node)
                    merged_items[idx] = (old_key_node, merged)
                else:
                    # last wins
                    merged_items[idx] = (old_key_node, v_node)
            else:
                index_map[k] = len(merged_items)
                merged_items.append((k_node, v_node))
        return MappingNode(tag=m1.tag, value=merged_items)

    result = []
    key_index = {}
    for key_node, val_node in nodes:
        k = key_node.value
        if k in key_index:
            idx = key_index[k]
            old_key_node, old_val_node = result[idx]
            if isinstance(old_val_node, MappingNode) and isinstance(val_node, MappingNode):
                merged_val = merge_mapping_nodes(old_val_node, val_node)
                result[idx] = (old_key_node, merged_val)
            else:
                # last wins
                result[idx] = (old_key_node, val_node)
        else:
            key_index[k] = len(result)
            result.append((key_node, val_node))
    return result

def deep_merge_nodes(nodes):
    '''
    Deep merge nodes with duplicate keys.
    '''
    def is_mapping(node):
        return hasattr(node, 'tag') and (node.tag == 'tag:yaml.org,2002:map' or node.__class__.__name__ == 'MappingNode')

    def merge_two_nodes(a, b):
        if is_mapping(a) and is_mapping(b):
            # Merge MappingNodes
            merged = list(a.value)  # copy left entries
            right_entries = b.value
            for r_key, r_val in right_entries:
                found = False
                for idx, (l_key, l_val) in enumerate(merged):
                    if hasattr(l_key, 'value') and l_key.value == r_key.value:
                        merged[idx] = (l_key, merge_two_nodes(l_val, r_val))
                        found = True
                        break
                if not found:
                    merged.append((r_key, r_val))
            return type(a)(tag=a.tag, value=merged)
        else:
            return b

    order = []
    seen = {}
    for key_node, val_node in nodes:
        key = getattr(key_node, 'value', None)
        if key in seen:
            existing_key_node, existing_val_node = seen[key]
            merged_val_node = merge_two_nodes(existing_val_node, val_node)
            seen[key] = (existing_key_node, merged_val_node)
        else:
            seen[key] = (key_node, val_node)
            order.append(key)

    result = []
    for key in order:
        result.append(seen[key])
    return result

