def bash_completion():
    import argparse
    try:
        from borgmatic import __main__ as bm_main
        parser = None
        for name in dir(bm_main):
            obj = getattr(bm_main, name)
            if isinstance(obj, argparse.ArgumentParser):
                parser = obj
                break
        if parser is None and hasattr(bm_main, 'get_parser'):
            try:
                parser = bm_main.get_parser()
            except Exception:
                parser = None
    except Exception:
        parser = None

    completions = []
    if parser:
        def gather(p):
            for action in p._actions:
                if isinstance(action, argparse._SubParsersAction):
                    for sub in action.choices.values():
                        gather(sub)
                else:
                    completions.extend(action.option_strings)
        gather(parser)

    completions_str = " ".join(sorted(set(completions)))

    script = f'''_borgmatic_complete()
{{
    local cur prev words cword
    _init_completion || return
    local completions="{completions_str}"
    COMPREPLY=( $(compgen -W "$completions" -- "$cur") )
}}
complete -F _borgmatic_complete borgmatic
'''
    return script

def bash_completion():
    """
    Return a bash completion script for the borgmatic command by introspecting
    borgmatic's argparse parsers. The generated script provides completion for
    options and subcommands defined in borgmatic's CLI.
    """
    try:
        # Attempt to import the function that returns the main argparse parser
        try:
            from borgmatic.cli.main import get_parser
        except Exception:
            from borgmatic.cli import get_parser
        parser = get_parser()
    except Exception:
        # Couldn't import or obtain the parser; return an empty script
        return ''

    options = set()
    # Gather option flags and dests
    import argparse
    for action in parser._actions:
        # Option strings are like '--create', '-c'
        if getattr(action, 'option_strings', None):
            options.update(action.option_strings)
        # Positional arguments
        elif action.dest and action.dest != 'help':
            options.add(action.dest)

        # Subcommands are stored in a SubParsersAction
        if isinstance(action, argparse._SubParsersAction):
            options.update(action.choices.keys())

    opts_str = ' '.join(sorted(options))

    script = '''
_borgmatic_completion()
{{
    local cur=${{COMP_WORDS[COMP_CWORD]}}
    local prev=${{COMP_WORDS[COMP_CWORD-1]}}
    COMPREPLY=()
    local opts="{opts}"
    COMPREPLY=( $(compgen -W "$opts" -- $cur) )
}}
complete -F _borgmatic_completion borgmatic
'''.format(opts=opts_str)
    return script

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
