def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    # Support placeholder format {key}
    for key, value in url_args.items():
        placeholder = '{%s}' % key
        url = url.replace(placeholder, str(value))
    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    # Build a mapping of placeholder names to string values
    if isinstance(url_args, (list, tuple)):
        mapping = {str(i): str(v) for i, v in enumerate(url_args)}
    else:
        mapping = {str(k): str(v) for k, v in url_args.items()}

    import re
    # Pattern matches {key}, ${key}, or %(key)s placeholders
    pattern = re.compile(r'({\w+}|\$\{\w+\}|\%\(\w+\)s)')
    def _repl(match):
        token = match.group(0)
        if token.startswith('{') and token.endswith('}'):
            key = token[1:-1]
        elif token.startswith('${') and token.endswith('}'):
            key = token[2:-1]
        else:  # old style %(key)s
            key = token[2:-2]
        return mapping.get(key, token)
    return pattern.sub(_repl, url)

