def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string using the provided alphabet.
    The most significant digit appears first.
    """
    if not alphabet:
        raise ValueError("Alphabet must contain at least one character")
    base = len(alphabet)
    # Handle negative numbers by prefixing '-'
    prefix = ''
    if number < 0:
        prefix = '-'
        number = -number
    # Convert to base representation
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        digits.reverse()
    # Apply padding if requested
    if padding is not None:
        pad_len = padding - len(digits) - len(prefix)
        if pad_len > 0:
            digits = [alphabet[0]] * pad_len + digits
    return prefix + ''.join(digits)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("int_to_string only supports non-negative integers")
    if not alphabet:
        raise ValueError("alphabet must contain at least one symbol")
    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        # digits are least significant first, reverse to most significant first
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None:
        if padding < 0:
