    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    def _pattern_to_regex(pat):
        # Convert wildcard patterns to regex patterns
        # Escapes all regex meta except * and ?
        escaped = []
        for ch in pat:
            if ch == '*':
                escaped.append('.*')
            elif ch == '?':
                escaped.append('.')
            else:
                escaped.append(re.escape(ch))
        regex = '^' + ''.join(escaped) + '$'
        return regex

    return { _pattern_to_regex(key): value for key, value in item.items() }

