def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Determine effective platform
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1

    # POSIX splitting using shlex
    if platform == 1:
        return shlex.split(s, posix=True)

    # Simplified Windows CMD splitting
    result = []
    current = []
    in_quote = False
    quote_char = ''
    escape = False

    for ch in s:
        if escape:
            current.append(ch)
            escape = False
        elif ch == '\\':
            # Backslash escapes next character
            escape = True
        elif ch in ('"', "'"):
            if in_quote:
                if ch == quote_char:
                    in_quote = False
                    quote_char = ''
                else:
                    current.append(ch)
            else:
                in_quote = True
                quote_char = ch
        elif ch.isspace() and not in_quote:
            if current:
                result.append(''.join(current))
                current = []
        else:
            current.append(ch)

    if current:
        result.append(''.join(current))

    return result

def split(s, platform='this'):
    import shlex, sys
    # Determine the parsing mode
    if platform == 'this':
        # Auto-detect current platform
        plat = sys.platform.lower()
        if plat.startswith('win'):
            mode = 0  # Windows
        else:
            mode = 1  # POSIX
    else:
        mode = int(platform)

    if mode == 1:  # POSIX
        # Fast regex that captures quoted and unquoted tokens.
        # It does not handle all edge cases of shlex, but is a
        # good compromise for speed.
        token_re = re.compile(
            r'''
            (?:"((?:\\.|[^"\\])*)"    # double‑quoted
            |'((?:\\.|[^'\\])*)'      # single‑quoted
            |([^ \t\r\n]+))            # unquoted
            ''',
            re.VERBOSE)
        parts = []
        for m in token_re.finditer(s):
            dq, sq, tok = m.groups()
            if dq is not None:
                parts.append(dq)
            elif sq is not None:
                parts.append(sq)
            else:
                parts.append(tok)
        # Unescape backslash escapes inside tokens
        def unescape(t):
            return re.sub(r'\\(.)', r'\1', t)
        return [unescape(p) for p in parts]

    elif mode == 0:  # Windows/CMD (POSIX=False)
        # shlex with posix=False implements the rules used by
        # CreateProcess on Windows, which include handling of
        # backslashes before quotes.
        # The outer shlex.split call will perform all the proper
        # escaping & unquoting needed for the subprocess API.
        return shlex.split(s, posix=False)

    else:
        raise ValueError(f'Unsupported platform: {platform}')

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import shlex
    import sys
    import os

    # Resolve platform if set to 'this'
    if platform == 'this':
        if os.name == 'nt' or sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1

    # POSIX style splitting
    if platform in (1, '1'):
        return shlex.split(s, posix=True)

    # Windows CMD style splitting
    if platform in (0, '0'):
        lexer = shlex.shlex(s, posix=False)
        lexer.whitespace_split = True
        lexer.commenters = ''
        lexer.quotes = '"'
        lexer.escape = '\\'
        return list(lexer)

    raise ValueError(f"Unsupported platform: {platform}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    import subprocess
    from pathlib import Path

    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive not found: {archive}")

    base_dir = Path(tmp_path).expanduser()
    base_dir.mkdir(parents=True, exist_ok=True)

    dest_name = filename or archive.stem
    dest_dir = base_dir / dest_name
    dest_dir.mkdir(parents=True, exist_ok=True)

    lower_name = archive.name.lower()
    cmd = None

    if lower_name.endswith(".zip"):
        cmd = ["unzip", "-q", str(archive), "-d", str(dest_dir)]
    elif lower_name.endswith(".tar.gz") or lower_name.endswith(".tgz"):
        cmd = ["tar", "xf", str(archive), "-C", str(dest_dir)]
    elif lower_name.endswith(".tar.bz2"):
        cmd = ["tar", "xjf", str(archive), "-C", str(dest_dir)]
    elif lower_name.endswith(".tar.xz"):
        cmd = ["tar", "xJf", str(archive), "-C", str(dest_dir)]
    elif lower_name.endswith(".tar"):
        cmd = ["tar", "xf", str(archive), "-C", str(dest_dir)]
    else:
        raise ValueError(f"Unsupported archive format: {archive}")

    subprocess.run(cmd, check=True)

    repo_dir = None
    if (dest_dir / ".git").is_dir():
        repo_dir = dest_dir
    else:
        for entry in dest_dir.iterdir():
            if entry.is_dir() and (entry / ".git").is_dir():
                repo_dir = entry
                break

    if repo_dir is None:
        raise FileNotFoundError(
            f"Could not find a .git directory inside extracted archive at '{dest_dir}'"
        )

    return f"file://{repo_dir.resolve()}"

