def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or str(frequency).strip().lower() == "always":
        return None

    import re
    freq_str = str(frequency).strip().lower()
    match = re.match(r'^(\d+(?:\.\d+)?)\s*(\w+)$', freq_str)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    value_str, unit = match.groups()
    try:
        value = float(value_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {value_str}")

    # Mapping of unit to timedelta parameter name
    unit_mapping = {
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
    }

    param = unit_mapping.get(unit)
    if param is None:
        raise ValueError(f"Unknown time unit in frequency: {unit}")

    # Ensure integer values for days, weeks, hours, minutes, seconds
    # float values are allowed but cast to int if close to integer
    if param in ('days', 'weeks', 'hours', 'minutes', 'seconds'):
        if abs(value - round(value)) < 1e-9:
            value = int(round(value))
        else:
            if param == 'seconds':
                # allow fractional seconds
                pass
            else:
                raise ValueError(f"Non-integer value for unit '{unit}' not allowed: {value}")

    kwargs = {param: value}
    return datetime.timedelta(**kwargs)

