            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip == "127.0.0.1" or ip == "0.0.0.0" or ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == "::1":
                    return True
    except Exception:
        # If the host cannot be resolved, it is not considered local
        pass
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Resolve the host to its IP addresses
        addr_info = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Host could not be resolved, so it's not localhost
        return False

    for family, _, _, _, sockaddr in addr_info:
        # IPv4 address
        if family == socket.AF_INET:
            ip = sockaddr[0]
            # Any address in the 127.0.0.0/8 block is loopback
            if ip.startswith("127."):
                return True
        # IPv6 address
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            # The sole IPv6 loopback address
            if ip == "::1":
                return True
    return False

def is_local(host):
    """
    Checks if the host is the localhost.

    :param host: The hostname or IP address.
    :return: True if the host resolves to a loopback address, otherwise False.
    """
    if not host:
        return False
    host = host.strip()
    try:
        for result in socket.getaddrinfo(host, None):
            ip = result[4][0]
            if ip == '127.0.0.1' or ip == '::1':
                return True
    except socket.gaierror:
        return False
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Quick direct checks for common localhost names
        if host == "localhost":
            return True
        if host == "127.0.0.1":
            return True
        if host == "::1":
            return True

        # Resolve the host to its IP addresses and check if any are loopback
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ip = sockaddr[0]
                # IPv4 loopback is 127.0.0.0/8
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                # IPv6 loopback is ::1
                if ip == "::1":
                    return True
        return False
    except Exception:
        # If resolution fails or any other error occurs, consider it not localhost
        return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.
    """
    transformed = []
    for frag in find_paths:
        # Assume a string containing a colon is already a pattern (e.g., "pp:root/somedir")
        if ':' in frag:
            transformed.append(frag)
        else:
            transformed.append(f'sh:**/*{frag}*/**')
    return transformed

def is_gitbash():
    """
    returns True if you run in a Windows gitbash
    """
    if os.name != 'nt':
        return False
    msystem = os.environ.get('MSYSTEM', '')
    return msystem.lower().startswith('mingw')

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''    
    # Support two forms: "VAR" or "VAR:default"
    if ':' in matcher:
        name, default = matcher.split(':', 1)
        default = default.strip()
    else:
        name, default = matcher, None

    name = name.strip()
    value = os.getenv(name)

    # If the environment variable is missing (or empty), use the default if provided
    if value is None or value == '':
        if default is not None:
            value = default
        else:
            raise KeyError(f'Environment variable "{name}" not found and no default provided')

    return value

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # If matcher is a plain string, treat it as "VAR_NAME|default" or just "VAR_NAME"
    if isinstance(matcher, str):
        parts = matcher.split("|", 1)
        name = parts[0]
        default = parts[1] if len(parts) > 1 else None
    # If matcher appears to be a regex match object
    elif hasattr(matcher, "group"):
        try:
            name = matcher.group(1)
        except IndexError:
            name = None
        try:
            default = matcher.group(2)
        except IndexError:
            default = None
    else:
        # Fallback: try to interpret matcher as a mapping with 'name' and 'default'
        try:
            name = matcher["name"] if isinstance(matcher, dict) else str(matcher)
        except Exception:
            name = str(matcher)
        default = None

    if not name:
        raise RuntimeError("Matcher did not provide an environment variable name")

    value = os.getenv(name)
    if value is not None:
        return value

    if default is not None:
        return default

    raise RuntimeError(f"Environment variable '{name}' not set and no default supplied")

def remove_ending_os_sep(input_list):
    if not isinstance(input_list, list):
        raise TypeError("input_list must be a list")
    processed = []
    for item in input_list:
        if not isinstance(item, str):
            raise TypeError("All items in input_list must be strings")
        if len(item) > 1 and item[-1] == os.sep:
            processed.append(item[:-1])
