    return processed

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern by escaping all
    special regex characters. Optionally it strips surrounding whitespace.
    It returns a compiled regular expression object.
    """
    if not isinstance(pattern, str):
        pattern = str(pattern)
    if strip:
        pattern = pattern.strip()
    escaped = re.escape(pattern)
    return re.compile(escaped)

