def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the final command list or string
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
        if args:
            if isinstance(args, (list, tuple)):
                cmd.extend(args)
            else:
                # treat args as string and split by whitespace
                cmd.extend(args.split())
    else:
        # commands is assumed to be a string
        cmd = commands
        if args:
            if isinstance(args, (list, tuple)):
                # join args into a string safely
                arg_str = " ".join(args)
            else:
                arg_str = args
            cmd = f"{cmd} {arg_str}"
    # Prepare subprocess parameters
    run_kwargs = {
        "cwd": cwd,
        "env": env,
        "text": True
    }
    if hide_stderr:
        run_kwargs["stderr"] = subprocess.DEVNULL
    if isinstance(commands, (list, tuple)):
        # Non-shell execution for list commands
        run_kwargs["shell"] = False
        run_kwargs["capture_output"] = True
    else:
        # Shell execution for string commands
        run_kwargs["shell"] = True
        run_kwargs["capture_output"] = True
    if verbose:
        print(f"Running command: {cmd}")
    proc = subprocess.run(cmd, **run_kwargs)
    return proc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Ensure commands is a list.
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)
    # Append arguments.
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(str(args))
    # Determine how to handle stderr.
    stderr_setting = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    # Execute the command.
    result = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=stderr_setting,
        text=True,
    )
    # Verbose logging if requested.
    if verbose:
        print("Command:", " ".join(cmd))
        if result.stdout:
            print("STDOUT:")
            print(result.stdout)
        if not hide_stderr and result.stderr:
            print("STDERR:")
            print(result.stderr)
    return result)

