def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json
    import os
    import re

    configs = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except FileNotFoundError as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Configuration file not found: {filename}',
                args=(),
                exc_info=exc
            )
            log_records.append(record)
            continue
        except json.JSONDecodeError as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=exc.lineno or 0,
                msg=f'JSON parse error in {filename}: {exc.msg}',
                args=(),
                exc_info=exc
            )
            log_records.append(record)
            continue
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Unexpected error loading {filename}: {exc}',
                args=(),
                exc_info=exc
            )
            log_records.append(record)
            continue

        if resolve_env:
            def _replace_env(value):
                if isinstance(value, str):
                    # Replace ${VAR} with environment variable
                    def repl(match):
                        var_name = match.group(1)
                        return os.getenv(var_name, '')
                    return re.sub(r'\$\{([^}]+)\}', repl, value)
                elif isinstance(value, dict):
                    return {k: _replace_env(v) for k, v in value.items()}
                elif isinstance(value, list):
                    return [_replace_env(v) for v in value]
                else:
                    return value
            data = _replace_env(data)

        if overrides:
            # Basic shallow merge: override top-level keys
            if isinstance(overrides, dict):
                data.update(overrides)

        configs[filename] = data

    return configs, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    # Use dynamic imports to avoid top-level import statements
    json_module = __import__('json')
    os_module = __import__('os')

    config_dict = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                content = f.read()
            # Parse JSON
            config = json_module.loads(content)
        except Exception as e:
            # Create a LogRecord for the parse error
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg='Failed to parse configuration file {}: {}'.format(filename, e),
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        # Apply environment variable resolution if requested
        if resolve_env:
            def resolve_value(value):
                if isinstance(value, str):
                    # Replace ${VAR} with environment variable value if present
                    if value.startswith('$(') and value.endswith(')'):
                        var_name = value[2:-1]
                        return os_module.getenv(var_name, value)
                    # Find patterns like ${VAR} inside string
                    import re
                    pattern = re.compile(r'\$\{([^}]+)\}')
                    def repl(match):
                        return os_module.getenv(match.group(1), match.group(0))
                    return pattern.sub(repl, value)
                elif isinstance(value, dict):
                    return {k: resolve_value(v) for k, v in value.items()}
                elif isinstance(value, list):
                    return [resolve_value(v) for v in value]
                return value
            config = resolve_value(config)

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            config.update(overrides)

        config_dict[filename] = config

    return config_dict, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, re, logging, types

    # Helper to recursively replace environment variables in values
    env_pattern = re.compile(r'\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)')

    def _replace_env(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1) or match.group(2)
                return os.getenv(var, '')
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _replace_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_replace_env(v) for v in value]
        else:
            return value

    # Helper to apply overrides to the config dict
    def _apply_overrides(cfg, overrides_dict):
        for k, v in overrides_dict.items():
            cfg[k] = v

    configs = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                cfg = json.load(f)

            if resolve_env:
                cfg = _replace_env(cfg)

            if overrides:
                _apply_overrides(cfg, overrides)

            configs[filename] = cfg

        except FileNotFoundError as fnf_err:
            exc_info = (fnf_err.__class__, fnf_err, fnf_err.__traceback__)
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Configuration file not found: {filename}',
                args=(),
                exc_info=exc_info
            )
            error_records.append(record)
        except json.JSONDecodeError as json_err:
            exc_info = (json_err.__class__, json_err, json_err.__traceback__)
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Invalid JSON in configuration file: {filename}',
                args=(),
                exc_info=exc_info
            )
            error_records.append(record)
        except Exception as e:
            exc_info = (e.__class__, e, e.__traceback__)
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error loading configuration file: {filename}',
                args=(),
                exc_info=exc_info
            )
            error_records.append(record)

    return configs, error_records

