def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the registry of handlers.  Subclasses may expose this
    # through a class attribute called `_protocol_handlers`.  Use
    # `getattr` so that the method works even if the attribute is
    # missing (in which case an empty dict is returned).
    handlers = getattr(cls, "_protocol_handlers", {})

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )
        # Return a new dictionary containing only the requested
        # protocol version if it is supported.
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        else:
            return {}
    else:
        # Return the entire registry as a shallow copy to avoid
        # accidental mutation of the class attribute.
        return dict(handlers)

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is None:
            # Return a copy so callers can't mutate internal registry
            return dict(cls._handlers)
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple or None, got {type(protocol_version)!r}"
            )
        # If exact match found, return a single-item dict; otherwise empty dict
        return (
            {protocol_version: cls._handlers[protocol_version]}
            if protocol_version in cls._handlers
            else {}
        )

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Accept any iterable; if None, start with an empty list.
    if values is None:
        raw_items = []
    else:
        raw_items = list(values)

    bookmarks = []
    for raw in raw_items:
        if not isinstance(raw, str):
            continue
        raw = raw.strip()
        if not raw:
            continue
        try:
            # Attempt to parse each raw string into a Bookmark instance.
            bookmark = Bookmark.from_raw_value(raw)
        except Exception:
            # If parsing fails, keep the raw string as a fallback.
            bookmark = raw
        bookmarks.append(bookmark)

    # Instantiate the Bookmarks object with the list of parsed bookmarks.
    # This assumes the constructor accepts a list of bookmark objects or
    # raw strings. Adjust if the actual constructor signature differs.
    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    seq_type = type(seq)
    # If seq is already a sequence (has __len__) we can return it unchanged.
    if hasattr(seq, "__len__"):
        return seq, seq_type

    # Otherwise seq must be iterable; gather its items.
    if bufsize is not None:
        result = []
        for i, item in enumerate(seq):
            if i >= bufsize:
                break
            result.append(item)
    else:
        # If seq is a generator or iterator, exhaust it into a list.
        result = list(seq)
    return result, seq_type

def _get_seq_with_type(seq, bufsize=None):
