    """
    # A positive or ``None`` bufsize does not change the behaviour in the
    # current implementation, but the argument is kept for API compatibility.
    # ``Sequence`` covers all common sequence types: list, tuple, str,
    # bytes, bytearray, and any custom classes that provide ``__len__`` and
    # ``__getitem__``.
    from collections.abc import Sequence

    # Preserve ``None`` unchanged
    if seq is None:
        return seq, type(seq)

    # If the object already behaves like a sequence, return it verbatim
    if isinstance(seq, Sequence):
        return seq, type(seq)

    # If the object provides a length and item access, treat it as a
    # sequence (e.g., array.array).  Otherwise fall back to iterating.
    try:
        if hasattr(seq, "__len__") and hasattr(seq, "__getitem__"):
            return seq, type(seq)
    except Exception:
        pass

    # Default: consume the iterator/generator into a tuple
    seq_tuple = tuple(seq)
    return seq_tuple, type(seq_tuple)

