    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a plain sequence type, return it as is.
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)

    # Detect a NumPy ndarray if available
    _np = None
    try:
        import numpy as _np  # noqa: F401
    except ImportError:
        pass
    if _np is not None and isinstance(seq, _np.ndarray):
        return seq, type(seq)

    # Try to iterate over seq; if that fails, wrap the value in a singleton list.
    try:
