    from collections.abc import Sequence
    # If seq is already a sequence, return it unchanged
    if isinstance(seq, Sequence):
        return seq, type(seq)
    # If seq is iterable but not a sequence (e.g. generator), materialize it
    try:
        derived_seq = list(seq)
    except TypeError:
        raise TypeError(f"Object of type {type(seq).__name__} is not iterable")
    return derived_seq, type(derived_seq)

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new scale requested
    if other is None:
        return getattr(self, "_scale", None)

    # Validate that the new scale is numeric
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value")

    # Current scale must be known and non‑zero
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale: graph has unknown or zero scale")

    # Compute the rescaling factor
    ratio = other / current_scale

    # Rescale the last coordinate (and its errors) in all data points
    fields = getattr(self, "fields", None)
    if fields and isinstance(fields, (list, tuple)):
        idx = len(fields) - 1
        data = getattr(self, "data", None)
        if data is not None:
            for point in data:
                if isinstance(point, dict):
                    if fields[idx] in point:
                        point[fields[idx]] *= ratio
                else:
                    if isinstance(point, list):
                        point[idx] *= ratio
                    elif hasattr(point, "__getitem__"):
                        # Tuple or similar
                        # Re‑build the point to preserve immutability
                        new_point = list(point)
                        new_point[idx] = new_point[idx] * ratio
                        point.__class__ = type(new_point)  # pragma: no cover
                        point[:] = new_point
        # Rescale errors if present
        errors = getattr(self, "errors", None)
        if errors is not None:
            for err_point in errors:
                if isinstance(err_point, dict):
                    if fields[idx] in err_point:
                        err_point[fields[idx]] *= ratio
                else:
                    if isinstance(err_point, list):
                        err_point[idx] *= ratio
                    elif hasattr(err_point, "__getitem__"):
                        new_err = list(err_point)
                        new_err[idx] = new_err[idx] * ratio
                        err_point.__class__ = type(new_err)  # pragma: no cover
                        err_point[:] = new_err

    # Update the stored scale
    self._scale = other
    return self

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Get current scale
    current_scale = getattr(self, "_scale", None)

    if other is None:
        return current_scale

    # Validate new scale
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value")

    if current_scale is None or current_scale == 0:
        # Assume LenaValueError is defined in the surrounding module
        raise NameError("Current scale is unknown or zero")  # fallback error

    # Compute scaling factor
    try:
        factor = other / current_scale
    except ZeroDivisionError:
        raise NameError("Current scale is zero, cannot rescale")

    # Rescale the last coordinate(s) in the graph's data points
    # Try commonly used attribute names; if none present, do nothing
    data_attrs = ["_data", "data", "values", "points"]
    for attr in data_attrs:
        if hasattr(self, attr):
            points = getattr(self, attr)
            if isinstance(points, list):
                for p in points:
                    if isinstance(p, (list, tuple)) and len(p) > 0:
                        # operate in-place if possible, else create new list
                        if isinstance(p, list):
                            p[-1] = p[-1] * factor
                        else:
                            # for tuple, replace whole point (unlikely to happen)
                            new_point = tuple(float(val) if i == len(p)-1 else val for i, val in enumerate(p))
                            # Cannot reassign to original container if it's a tuple element
                            # skip in this case
                            pass
            break

    # Rescale errors if present
    err_attrs = ["_errors", "errors", "error_data"]
    for attr in err_attrs:
        if hasattr(self, attr):
            errors = getattr(self, attr)
            if isinstance(errors, list):
                for e in errors:
                    if isinstance(e, (list, tuple)) and len(e) > 0:
                        if isinstance(e, list):
                            e[-1] = e[-1] * factor
                        else:
                            # skip immutable tuples
                            pass
            break

    # Update the stored scale
    setattr(self, "_scale", float(other))

    # Return self to allow chaining
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph."""
    if make_value is None:
        def make_value(b): 
            return b.content if hasattr(b, "content") else b
    # Resolve coordinate getter
    coord_funcs = {
        "left":     lambda b: b.left   if hasattr(b, "left")   else (b.low  if hasattr(b, "low")   else None),
        "right":    lambda b: b.right  if hasattr(b, "right")  else (b.high if hasattr(b, "high")  else None),
        "middle":   lambda b: ((b.left + b.right) / 2
                               if hasattr(b, "left") and hasattr(b, "right")
                               else ((b.low + b.high) / 2) 
                               if hasattr(b, "low") and hasattr(b, "high") else None)
    }
    get_coord = coord_funcs.get(get_coordinate)
    if get_coord is None:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    # Determine scale
    if scale is True:
        scale_val = getattr(hist, "scale", None)
    else:
        scale_val = scale

    points = []
    # Iterate over bins; assume hist has iterable of bins
    for bin_ in hist:
        x_coord = get_coord(bin_)
        y_val = make_value(bin_)
        # If make_value returns a tuple or list, convert to list
        if isinstance(y_val, tuple) or isinstance(y_val, list):
            y_vals = list(y_val)
        else:
            y_vals = [y_val]
        # Ensure number of y values matches remaining field names
        if len(y_vals) + 1 != len(field_names):
            # Pad with None if mismatch
            y_vals += [None] * (len(field_names) - len(y_vals) - 1)
        point = (x_coord, *y_vals)
        points.append(point)
    return {"field_names": field_names, "points": points, "scale": scale_val}

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.
    This involves:
        - Making sure the candidate claims that it provides the interface using
          ``iface.providedBy`` (unless *tentative* is True).
        - Making sure the candidate defines all the necessary methods.
        - Making sure the methods have the correct signature (to the extent possible).
        - Making sure the candidate defines all the necessary attributes.
    """
    if vtype is None:
        try:
            from zope.interface import Invalid
        except Exception:
            Invalid = Exception
        vtype = Invalid
    errors = []

    # 1. Interface provision check
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"{candidate!r} does not provide required interface {iface!r}"
                )
        except Exception as exc:
            errors.append(f"Error while checking interface provision: {exc}")

    # 2. Required attributes and methods
    # Use introspection to obtain needed names; fall back to empty sets if unavailable.
    req_attrs = getattr(iface, "requiredAttributes", getattr(iface, "_requiredAttributes", set()))
    req_methods = getattr(iface, "requiredMethods", getattr(iface, "_requiredMethods", set()))

    for name in required_attrs := req_attrs or set():
        if not hasattr(candidate, name):
            errors.append(f"Missing required attribute {name!r}")
    for name in required_methods := req_methods or set():
        if not hasattr(candidate, name):
            errors.append(f"Missing required method {name!r}")
        else:
            ok = getattr(candidate, name)
            if not callable(ok):
                errors.append(f"Required attribute {name!r} is not callable")

    # 3. Signature checking (basic: parameters only)
    import inspect  # Import inside function to avoid global imports.
    for name in required_methods:
        iface_member = getattr(iface, name, None)
        cand_member = getattr(candidate, name, None)
        if iface_member is None or cand_member is None:
            continue
        try:
            iface_sig = inspect.signature(iface_member)
            cand_sig = inspect.signature(cand_member)
            if iface_sig.parameters != cand_sig.parameters:
                errors.append(
                    f"Signature mismatch for method {name!r}: "
                    f"expected {iface_sig}, got {cand_sig}"
                )
        except Exception:
            # skip if anything goes wrong; we won't pretend to be exhaustive.
            pass

    # 4. Throw collected errors or return True
    if errors:
        if len(errors) == 1:
            raise vtype(errors[0])
        else:
            raise vtype(", ".join(errors))
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    Checks that `candidate` defines all attributes and methods required by
    `iface`.  For callable attributes the signatures are compared (ignoring
    the implicit ``self``/``cls`` when present).  If a mismatch is found the
    function raises a :class:`TypeError`, unless *tentative* is true, in
    which case ``False`` is returned.  On success ``True`` is returned.
    """
    import inspect

    # Convenience: if both are classes and inheritance actually suffices
    try:
        if inspect.isclass(iface) and inspect.isclass(candidate):
            if issubclass(candidate, iface):
                return True
    except Exception:
        # In case of non-standard types; fall back to attribute checks
        pass

    def _check_method(name, iface_attr, cand_attr):
        try:
            iface_sig = inspect.signature(iface_attr)
        except (ValueError, TypeError):
            # ignore attributes with no signature (e.g. properties)
            return True
        try:
            cand_sig = inspect.signature(cand_attr)
        except (ValueError, TypeError):
            # Candidate may be a built-in method; skip exact comparison
            return True

        # Drop implicit first parameter if it's "self" or "cls" for instance/static methods
        iface_params = list(iface_sig.parameters.values())
        cand_params = list(cand_sig.parameters.values())

        if iface_params and iface_params[0].name in ("self", "cls"):
            iface_params = iface_params[1:]
        if cand_params and cand_params[0].name in ("self", "cls"):
            cand_params = cand_params[1:]

        if len(iface_params) != len(cand_params):
            raise TypeError(
                f"Signature mismatch for method '{name}': expected {iface_sig} but got {cand_sig}"
            )
        for iparam, cparam in zip(iface_params, cand_params):
            if iparam.kind != cparam.kind:
                raise TypeError(
                    f"Parameter kind mismatch in method '{name}': {iparam.kind} vs {cparam.kind}"
                )
        return True

    try:
        # Get a list of members from iface (excluding private and special)
        iface_members = {
            name: attr
            for name, attr in vars(iface).items()
            if not name.startswith("_")
        }

        for name, iface_attr in iface_members.items():
            # Skip properties: the descriptor will provide value in candidate
            if isinstance(iface_attr, property):
                if not hasattr(candidate, name):
                    raise TypeError(
                        f"{candidate.__name__} missing property '{name}' required by {iface.__name__}"
                    )
                continue

            try:
                cand_attr = getattr(candidate, name)
            except AttributeError:
                # The attribute could be defined on base classes
                if not any(hasattr(base, name) for base in candidate.__mro__):
                    raise TypeError(
                        f"{candidate.__name__} missing attribute '{name}' required by {iface.__name__}"
                    )
                continue

            if callable(iface_attr):
                if not callable(cand_attr):
                    raise TypeError(
                        f"Attribute '{name}' of {candidate.__name__} is not callable but {iface.__name__} requires a callable"
                    )
                _check_method(name, iface_attr, cand_attr)
            else:
                # Non-callable attribute: just ensure it's present (type validation omitted)
                pass

        return True
    except Exception as exc:
        if tentative:
            return False
        raise

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Treat a candidate instance as its class
    cand_cls = candidate if isinstance(candidate, type) else candidate.__class__

    # Collect interface attributes that are expected to exist on candidate
    required = []
    for name in dir(iface):
        if name.startswith('_'):            # ignore special attributes
            continue
        required.append(name)

    # Check that each required attribute exists on the candidate class
    for name in required:
        if not hasattr(cand_cls, name):
            return False

        if not tentative:
            iface_attr = getattr(iface, name)
            cand_attr = getattr(cand_cls, name)
            # If both are callable and the candidate did not override
            # (i.e., they are the same function object), fail.
            try:
                if callable(iface_attr) and callable(cand_attr):
                    if iface_attr is cand_attr:
                        return False
            except Exception:
                pass

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if candidate is a subclass of iface or implements
    all callable attributes of iface that are not private (do not start with '_').
    Returns False otherwise.
    """
    # Determine the actual type or instance to work with
    target = candidate
    # Check subclass relationship if candidate is a class or path to a class
    if isinstance(candidate, type):
        ctype = candidate
    else:
        ctype = type(candidate)
    try:
        if issubclass(ctype, iface):
            return True
    except TypeError:
        # In case iface is not a class or ctype is not a class
        pass

    # Check that all public callable attributes of iface exist in the candidate
    for name in dir(iface):
        if name.startswith('_'):
            continue
        attr = getattr(iface, name, None)
        if callable(attr):
            if not hasattr(target, name):
                return False
            cand_attr = getattr(target, name)
            if not callable(cand_attr):
                return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass was provided, verify it is compatible with the bases.
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("Metaclass must be a class")
        # The explicit metaclass must be a subclass of all base metaclasses.
        base_mcs = [type(b) for b in bases]
        for mc in base_mcs:
            if not issubclass(explicit_mc, mc):
                raise TypeError(
                    "Metaclass conflict: explicit metaclass must be a subclass of "
                    "the metaclasses of all base classes"
                )
        return explicit_mc

    # No explicit metaclass: determine it from the bases.
    if not bases:
        return type

    # Gather the metaclasses of all bases.
    base_mcs = [type(b) for b in bases]

    # 1. Try to find a metaclass that is a subclass of all others.
    for candidate in base_mcs:
        if all(issubclass(candidate, other) for other in base_mcs):
            return candidate

    # 2. If none such, find the common ancestor that is subclass of all base metaclasses.
    #    Use the mro of the first metaclass to locate the lowest common ancestor.
    for potential in base_mcs[0].mro():
        if all(issubclass(other, potential) for other in base_mcs):
            return potential

    # 3. If unable to find a common metaclass, raise an error.
    raise TypeError("metaclass conflict: unable to find a common metaclass")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    if not bases:
        return type
    mcls = type(bases[0])
    for b in bases[1:]:
        bcls = type(b)
        if issubclass(mcls, bcls):
            # current mcls is already a subclass of bcls; keep it
            continue
        elif issubclass(bcls, mcls):
            # bcls is a more derived metaclass; adopt it
            mcls = bcls
        else:
            raise TypeError(
                f"metaclass conflict: the metaclass ({mcls}) of a derived class "
                f"is not a (non-abstract) subclass of the metaclass of one of its bases "
                f"({bcls})"
            )
    return mcls

def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        try:
            value = self[key]
        except KeyError:
            if default is __marker:
                raise
            return default
        del self[key]
        return value

def pop(self, key, default=__marker):
        if key in self:
            value = self[key]
            del self[key]
            return value
        if default is __marker:
            raise KeyError(key)
        return default

def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        if not self:
            raise KeyError("popitem(): dictionary is empty")
        freq = getattr(self, "freq", {})
        # Find the key with the smallest usage count
        key = min(self, key=lambda k: freq.get(k, 0))
        value = self.pop(key)
        if hasattr(self, "freq"):
            self.freq.pop(key, None)
        return (key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Assumes `self.cache` is an OrderedDict where the first item is the least recently used
    return self.cache.popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    return self.cache.popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to handle a doubly‑linked list implementation
    if hasattr(self, "head") and hasattr(self, "tail"):
        # The most recently used node is immediately after the head sentinel
        node = getattr(self.head, "next", None)
        if node is None or node is getattr(self, "tail", None):
            raise IndexError("popitem from an empty cache")
        # Unlink the node from the list
        self.head.next = node.next
        node.next.prev = self.head
        # Update dictionary reference if it exists
        if hasattr(self, "cache") and isinstance(self.cache, dict):
            self.cache.pop(node.key, None)
        # Decrement size counter if present
        if hasattr(self, "size"):
            self.size -= 1
        return node.key, node.val

    # Fallback to a dictionary‑based implementation
    if hasattr(self, "cache") and isinstance(self.cache, dict):
        try:
            key, value = self.cache.popitem()
        except KeyError:
            raise IndexError("popitem from an empty cache")
        if hasattr(self, "size"):
            self.size -= 1
        return key, value

    # If the cache itself is a plain dict
    if isinstance(self, dict):
        try:
            key, value = self.popitem()
        except KeyError:
            raise IndexError("popitem from an empty dict")
        return key, value

    raise TypeError("popitem requires 'cache' or linked‑list attributes")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    return self._cache.popitem(last=True)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError('pop from an empty container')
    return super().popitem(last=True)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not hasattr(self, "_order") or not hasattr(self, "_data"):
        raise AttributeError("Required attributes '_order' and '_data' are missing")
    if not self._order:
        raise KeyError("popitem(): dictionary is empty")
    key = self._order.pop()          # most recently used key
    value = self._data.pop(key)      # remove the entry from storage
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not getattr(self, 'cache', None):
        raise KeyError("Cache is empty")
    return self.cache.popitem(last=True)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError("dictionary is empty")
    # Iterate over a snapshot of keys to avoid modification issues
    for key in list(self.keys()):
        value = self.pop(key)
        return key, value

