def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a datetime.datetime.
    """
    import re, datetime
    from dateutil import tz

    if hasattr(dt_str, "read"):
        # iterator/stream
        dt_str = dt_str.read()
    dt_str = str(dt_str).strip()
    if not dt_str:
        raise ValueError("Empty string")

    # Separate date and time parts
    if "T" in dt_str:
        date_part, time_part = dt_str.split("T", 1)
    elif " " in dt_str:
        date_part, time_part = dt_str.split(" ", 1)
    else:
        date_part, time_part = dt_str, ""

    # Helper for ISO week parsing
    def parse_week(dpart):
        m = re.match(r"(?P<year>\d{4})[Ww]?-?(?P<week>\d{2})(?:-?(?P<weekday>\d))?$", dpart)
        if not m:
            raise ValueError(f"Bad ISO week date: {dpart}")
        y = int(m.group("year"))
        w = int(m.group("week"))
        dw = int(m.group("weekday") or 1)  # default Monday
        return datetime.date.fromisocalendar(y, w, dw)

    # Date parsing
    if re.search(r"[Ww]", date_part):
        date_obj = parse_week(date_part)
    else:
        m = re.match(r"(?P<year>\d{4})-?(?P<month>\d{2})?-?(?P<day>\d{2})?$", date_part)
        if not m:
            raise ValueError(f"Bad ISO date: {date_part}")
        y = int(m.group("year"))
        m2 = int(m.group("month") or 1)
        d = int(m.group("day") or 1)
        date_obj = datetime.date(y, m2, d)

    # Default time components
    hour = minute = second = microsecond = 0
    tzinfo = None

    # Handle time+tz
    if time_part:
        # Separate possible timezone offset
        tz_match = re.search(r"(Z|[+-]\d{2}(:?\d{2})?)$", time_part)
        if tz_match:
            tz_str = tz_match.group(0)
            time_str = time_part[:tz_match.start()]
        else:
            tz_str = None
            time_str = time_part

        if time_str:
            # Accept both ':' and no separator
            parts = time_str.replace(",", ".").split(":")
            hour = int(parts[0])
            if len(parts) > 1:
                minute = int(parts[1])
            if len(parts) > 2:
                sec_part = parts[2]
                if "." in sec_part:
                    s, frac = sec_part.split(".", 1)
                    second = int(s)
                    microsecond = int((frac + "000000")[:6])
                else:
                    second = int(sec_part)

        # 24:00 edge‑case
        if hour == 24 and minute == 0 and second == 0 and microsecond == 0:
            date_obj += datetime.timedelta(days=1)
            hour = 0

        # Timezone offset
        if tz_str:
            if tz_str == "Z":
                tzinfo = tz.tzutc()
            else:
