def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    # Pattern matches URLs starting with http://, https://, or www.
    url_pattern = re.compile(r'\b(?:https?://|www\.)[^\s<>()]+', re.IGNORECASE)

    def _linkify(match):
        url = match.group(0)
        href = url
        # If the URL starts with www., prepend http:// for the href
        if url.lower().startswith('www.'):
            href = 'http://' + url
        # Return the anchor tag with desired attributes
        return (
            f'<a href="{href}" target="_blank" '
            f'rel="noopener noreferrer" class="linkify">{url}</a>'
        )

    # Replace all matched URLs with anchor tags
    return url_pattern.sub(_linkify, text)

