    """Test a word whether it could be accepted as a tag."""
    # Tags must be nonempty, lowercase, and consist only of letters, digits, hyphens, or underscores.
    # They cannot start or end with a hyphen or underscore.
    if not isinstance(tag, str) or not tag:
        return False
    # Must be all lowercase (tags are case‑insensitive but stored in lowercase)
    if tag != tag.lower():
        return False
    # Allowed characters
    allowed = set("abcdefghijklmnopqrstuvwxyz0123456789-_")
    for ch in tag:
        if ch not in allowed:
            return False
    # Cannot start or end with '-' or '_'
    if tag[0] in '-_' or tag[-1] in '-_':
        return False
    return True

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # length must be between 1 and 35 characters
    if not (1 <= len(tag) <= 35):
        return False

    # must contain at least one letter
    has_letter = False

    # tag must not start or end with a hyphen
    if tag[0] == '-' or tag[-1] == '-':
        return False

    prev_char = ''
    for ch in tag:
        # allowed characters are lowercase letters, digits, and hyphens
        if not (('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch == '-'):
            return False

        if 'a' <= ch <= 'z':
            has_letter = True

        # no consecutive hyphens
        if prev_char == '-' and ch == '-':
            return False

        prev_char = ch

    return has_letter and len(tag) > 0

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Tag must be non-empty
    if not tag:
        return False
    # Common length limit (e.g., no longer than 30 characters)
    if len(tag) > 30:
        return False
    # Allowed characters: lowercase letters, digits, hyphens, and underscores
    for c in tag:
        if not (c.islower() or c.isdigit() or c in "-_"):
            return False
    # Optional: prevent tags that start or end with a hyphen or underscore
    if tag[0] in "-_":
        return False
    if tag[-1] in "-_":
        return False
    return True

def xml_children_as_dict(node):
    """
    Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        key = child.tag
        value = child.text
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(value)
                result[key] = existing
            else:
                result[key] = [existing, value]
        else:
            result[key] = value
    return result

