def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle is None or entity_handle is None:
        raise ValueError("Sender handle or entity handle cannot be None")
    if str(sender_handle) != str(entity_handle):
        raise ValueError(
            f"Sender handle {sender_handle!r} does not match entity handle {entity_handle!r}"
        )
    return True

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Normalise the base URL
    base = url.rstrip('/')
    # Default NodeInfo endpoint if none supplied
    if document_path is None:
        nodeinfo_path = '/nodeinfo/2.0'
    else:
        # Ensure it starts with a slash; otherwise prepend one
        nodeinfo_path = document_path if document_path.startswith('/') else '/' + document_path
    href = f"{base}{nodeinfo_path}"
    return {"links": [
        {
            "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
            "href": href
        }
    ]}

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if document_path is None:
        document_path = "/nodeinfo"
    # Normalize document_path
    if not document_path.startswith("/"):
        document_path = "/" + document_path
    document_path = document_path.rstrip("/")
    # Build absolute href
    href = url.rstrip("/") + document_path
    # NodeInfo spec recommends including both schema v2.0 and v1.0 links
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href,
            },
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href,
            },
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Imports are performed locally to avoid top-level import statements
    try:
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.exceptions import InvalidSignature
        import base64
        import xml.etree.ElementTree as ET
    except Exception:
        # If required libraries are not available, we cannot verify
        return False

    # Load the public key
    try:
        if isinstance(public_key, str):
            public_key_bytes = public_key.encode()
        else:
            public_key_bytes = public_key
        pub_key = serialization.load_pem_public_key(public_key_bytes)
    except Exception:
        # Public key could not be loaded
        return False

    # Prepare the data to verify
    try:
        if isinstance(doc, str):
            data = doc.encode()
        else:
            # Assume doc is an Element or ElementTree
            if hasattr(doc, 'getroot'):
                # ElementTree
                data = ET.tostring(doc.getroot(), encoding='utf-8')
            else:
                # Element
                data = ET.tostring(doc, encoding='utf-8')
    except Exception:
        return False

    # Decode the signature from base64
    try:
        sig_bytes = base64.b64decode(signature)
    except Exception:
        return False

    # Perform the verification
    try:
        pub_key.verify(
            sig_bytes,
            data,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except InvalidSignature:
        return False
    except Exception:
        # Any other error during verification indicates failure
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    JSON = __import__("json")
    try:
        data = JSON.loads(document)
    except Exception:
        ET = __import__("xml.etree.ElementTree")
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        root = ET.fromstring(document)
        subject = root.findtext("xrd:Subject", namespaces=ns)
        aliases = [a.text for a in root.findall("xrd:Alias", namespaces=ns)]
        links = [
            {"rel": l.get("rel"), "type": l.get("type"), "href": l.get("href")}
            for l in root.findall("xrd:Link", namespaces=ns)
        ]
        data = {"subject": subject, "aliases": aliases, "links": links}
    return data

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # First try JSON
    try:
        import json
        return json.loads(document)
    except Exception:
        # Fall back to XRD/XML parsing
        import xml.etree.ElementTree as ET

        def strip_ns(tag: str) -> str:
            # Removes namespace from an XML tag
            return tag.split("}", 1)[-1] if "}" in tag else tag

        root = ET.fromstring(document)
        subject: str | None = None
        aliases: list[str] = []
        links: list[dict] = []

        for elem in root.iter():
            tag = strip_ns(elem.tag).lower()
            if tag == "subject":
                if elem.text:
                    subject = elem.text.strip()
            elif tag == "alias":
                if elem.text:
                    aliases.append(elem.text.strip())
            elif tag == "link":
                link_dict: dict = {}
                # First add attributes of <Link>
                for k, v in elem.attrib.items():
                    link_dict[k] = v
                # Now add text of child elements (like Href, Title, Type)
                for child in elem:
                    key = strip_ns(child.tag)
                    value = child.text.strip() if child.text else None
                    link_dict[key] = value
                links.append(link_dict)

        result: Dict = {}
        if subject is not None:
            result["subject"] = subject
        if aliases:
            result["aliases"] = aliases
        if links:
            result["links"] = links
        return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        # Ensure it's a JRD-like dict
        subject = data.get("subject")
        links = data.get("links", [])
        return {"subject": subject, "links": links}
    except json.JSONDecodeError:
        pass

    # Try XRD (XML) format
    try:
        root = ET.fromstring(document)

        # Extract namespace if present
        ns = ""
        if root.tag.startswith("{"):
            ns = root.tag[1:root.tag.index("}")]
        def qname(tag):
            return f"{{{ns}}}{tag}" if ns else tag

        subject_elem = root.find(qname("Subject"))
        subject = subject_elem.text if subject_elem is not None else None

        links = []
        for link_elem in root.findall(qname("Link")):
            rel = link_elem.attrib.get("rel")
            href = link_elem.attrib.get("href")
            type_ = link_elem.attrib.get("type")
            links.append({"rel": rel, "uri": href, "type": type_})
        return {"subject": subject, "links": links}
    except ET.ParseError:
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try parsing as JSON
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            subject = data.get("subject")
            aliases = data.get("aliases", [])
            links = data.get("links", [])
            return {"subject": subject, "aliases": aliases, "links": links}
    except Exception:
        pass  # fall back to XRD parsing

    # Try parsing as XRD (XML)
    try:
        root = ET.fromstring(document)

        def _strip_ns(tag: str) -> str:
            return tag.split("}")[-1] if "}" in tag else tag

        # Find subject
        subject = None
        for elem in root.iter():
            if _strip_ns(elem.tag) == "Subject":
                subject = elem.text
                break

        # Find aliases
        aliases = [e.text for e in root.iter() if _strip_ns(e.tag) == "Alias" and e.text]

        # Find links
        links: list[dict] = []
        for link_elem in root.iter():
            if _strip_ns(link_elem.tag) == "Link":
                href = link_elem.attrib.get("href")
                if not href:
                    continue
                rel = link_elem.attrib.get("rel")
                link_info: dict = {"href": href}
                if rel:
                    link_info["rel"] = rel
                # Optional type
                for child in link_elem:
                    if _strip_ns(child.tag) == "Type":
                        link_info["type"] = child.text
                links.append(link_info)

        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception:
        # If we can't parse, return empty dict
        return {}

