def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json
    import re
    # Validate handle and extract domain
    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("Handle must be a string in the form 'user@example.com'")
    local_part, domain = handle.split('@', 1)
    if not local_part or not domain:
        raise ValueError("Handle must contain a local part and a domain")
    # Build resource parameter (percent-encoded)
    resource = urllib.parse.quote(f"acct:{handle}", safe='')
    url = f"https://{domain}/.well-known/webfinger?resource={resource}"
    try:
        req = urllib.request.Request(url, headers={'Accept': 'application/json'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                # Non-OK HTTP status; return empty dict
                return {}
            body = resp.read()
    except urllib.error.HTTPError as e:
        # Return empty dict on HTTP errors (e.g., 404)
        return {}
    except urllib.error.URLError:
        # Return empty dict on URL errors (e.g., network problems)
        return {}
    except Exception:
        # Catch all other exceptions and return empty dict
        return {}
    try:
        data = json.loads(body.decode('utf-8'))
    except Exception:
        return {}
    # The Diaspora-specific "Subject" is usually in the "subject" field.
    # We may want to normalize subject to lowercase for easier comparison.
    if 'subject' in data and isinstance(data['subject'], str):
        data['subject'] = data['subject'].lower()
    return data

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json

    # Validate handle format
    if '@' not in handle:
        raise ValueError(f"Handle '{handle}' is not a valid acct: form (missing '@')")

    domain = handle.split('@', 1)[1]
    if not domain:
        raise ValueError(f"Handle '{handle}' does not contain a domain part")

    # Build the WebFinger URL
    # Encode the resource query parameter
    resource = f'acct:{handle}'
    query = urllib.parse.urlencode({'resource': resource})
    url = f'https://{domain}/.well-known/webfinger?{query}'

    # Prepare the request with appropriate Accept header
    req = urllib.request.Request(url, headers={
        'Accept': 'application/jrd+json, application/json'
    })

    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                raise ValueError(f"HTTP error {resp.status} retrieving webfinger for {handle}")
            data = resp.read().decode('utf-8')
            try:
                json_data = json.loads(data)
            except json.JSONDecodeError as e:
                raise ValueError(f"Failed to parse JSON from webfinger response for {handle}: {e}")
            if not isinstance(json_data, dict):
                raise ValueError(f"Unexpected JSON structure from webfinger for {handle}")
            return json_data
    except urllib.error.HTTPError as e:
        raise ValueError(f"HTTP error retrieving webfinger for {handle}: {e.code} {e.reason}")
    except urllib.error.URLError as e:
        raise ValueError(f"URL error retrieving webfinger for {handle}: {e.reason}")

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        # Use the requests library to send the request. We assume requests is already imported.
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            # Generic request for other HTTP methods
            response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as err:
        # Return None for status code on failure and the exception instance
        return (None, err)

