    result = []
    for d in settings_dirs:
        try:
            for fname in os.listdir(d):
                if not spec_option:
                    result.append(fname)
                else:
                    # If spec_option looks like an extension (e.g., 'ini' or '.ini')
                    if spec_option.startswith('.'):
                        if fname.lower().endswith(spec_option.lower()):
                            result.append(fname)
                    else:
                        # Treat spec_option as a substring filter
                        if spec_option.lower() in fname.lower():
