            # Skip directories that cannot be accessed
            continue
    return result

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    os = __import__('os')
    files = []
    for directory in settings_dirs:
        if not os.path.isdir(directory):
            continue
        for entry in os.listdir(directory):
            full_path = os.path.join(directory, entry)
            if os.path.isfile(full_path):
                if spec_option is None or str(entry).endswith(str(spec_option)):
                    files.append(full_path)
    return files

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    file_names = []
    for path in settings_dirs:
        if isinstance(path, str):
            name = path.split('/')[-1].split('\\')[-1]
            if spec_option is None or name.endswith(spec_option) or spec_option in name:
                file_names.append(name)
    return file_names

def ansible_config_manager(cls):
    """Gets the ansible config manager."""
    # Import ansible context lazily to avoid unnecessary import costs
    from ansible import context
    # Ensure the context configuration is initialized
    try:
        if hasattr(context, 'setup'):
            context.setup()
    except Exception:
        # If setup fails or doesn't exist, ignore and continue
        pass
    # Return the configuration object; this is the common way to access Ansible configuration
    return getattr(context, "config", None)

