def _include_groups(self, parser_dict):
    """
    Recursively resolve an "include" directive present in a dictionary
    representation of a spec file.  The include key may contain either
    a mapping of group names to group definitions, a list of group names,
    or a single group name.  The referenced group(s) are merged into the
    current dictionary, overriding existing keys as necessary.
    The function mutates *parser_dict* in place and returns None.
    """
    seen = set()

    def _deep_merge(dest, src):
        for k, v in src.items():
            if isinstance(v, dict) and isinstance(dest.get(k, {}), dict):
                _deep_merge(dest[k], v)
            else:
                dest[k] = v

    def _process(d):
        if not isinstance(d, dict) or id(d) in seen:
            return
        seen.add(id(d))

        if "include" in d:
            inc = d.pop("include")
            if isinstance(inc, dict):
                # Merge each mapping entry into the current dictionary
                for key, val in inc.items():
                    if isinstance(val, dict):
                        if key in d and isinstance(d[key], dict):
                            _deep_merge(d[key], val)
                        else:
                            d[key] = val
                    else:
                        d[key] = val
            elif isinstance(inc, list):
                # Include each named group referenced in the list
                for key in inc:
                    if isinstance(key, str) and key in d:
                        val = d[key]
                        if isinstance(val, dict):
                            _deep_merge(d, val)
            elif isinstance(inc, str) and inc in d:
                val = d[inc]
                if isinstance(val, dict):
                    _deep_merge(d, val)

        # Recurse into any nested dicts or dicts contained within lists.
        for v in d.values():
            if isinstance(v, dict):
                _process(v)
            elif isinstance(v, list):
                for item in v:
                    if isinstance(item, dict):
                        _process(item)

    _process(parser_dict)

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Use a special key to indicate an include block. Adjust if your spec uses a
        # different name.
        include_key = "__include__"

        if include_key not in parser_dict:
            return parser_dict

        includes = parser_dict.pop(include_key)
        if not isinstance(includes, dict):
            raise ValueError(
                f"Include directive must be a dict, got {type(includes).__name__}"
            )

        # Prepare a new dict that will hold the merged content.
        merged = {}

        # First merge in every group that was explicitly included.
        for group_name, group_content in includes.items():
            if not isinstance(group_content, dict):
                raise ValueError(
                    f"Included group {group_name!s} must be a dict, got "
                    f"{type(group_content).__name__}"
                )
            merged[group_name] = group_content

        # Finally merge everything else from the original dict. If a key exists in
        # both the inclusion list and the original dict, and both values are dicts,
        # we perform a shallow merge of those dicts; otherwise the original value
        # wins.
        for key, value in parser_dict.items():
            if key in merged:
                if isinstance(merged[key], dict) and isinstance(value, dict):
                    merged[key] = {**merged[key], **value}
                else:
                    merged[key] = value
            else:
                merged[key] = value

        return merged

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.
    Returns a dictionary mapping argument names to their default values.
    """
    defaults = {}
    specs = getattr(self, "spec", {})
    # Handle spec defined as a dict of {arg_name: spec_dict}
    if isinstance(specs, dict):
        for name, spec in specs.items():
            if isinstance(spec, dict):
                if "default" in spec:
                    defaults[name] = spec["default"]
                elif "default_factory" in spec:
                    default_factory = spec["default_factory"]
                    if callable(default_factory):
                        try:
                            defaults[name] = default_factory()
                        except Exception:
                            # If calling the factory fails, store the factory itself
                            defaults[name] = default_factory
    # Handle spec defined as a list/tuple of spec dictionaries
    elif isinstance(specs, (list, tuple)):
        for spec in specs:
            if not isinstance(spec, dict):
                continue
            name = spec.get("name")
            if not name:
                continue
            if "default" in spec:
                defaults[name] = spec["default"]
            elif "default_factory" in spec:
                default_factory = spec["default_factory"]
                if callable(default_factory):
                    try:
                        defaults[name] = default_factory()
                    except Exception:
                        defaults[name] = default_factory
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    resolved = {}
    spec = getattr(self, 'spec', {})
    for name, arg_spec in spec.items():
        # Priority: user-provided args, environment variable, then spec default
        if hasattr(self, 'arguments') and name in self.arguments:
            resolved[name] = self.arguments[name]
            continue
        env_name = arg_spec.get('env', name.upper())
        if env_name in os.environ:
            resolved[name] = os.getenv(env_name)
            continue
        resolved[name] = arg_spec.get('default')
    return resolved

