def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Retrieve the mapping of deprecated arguments. It may be a dict
        # mapping argument names to deprecation messages, or simply a set/list
        # of names. Normalise to a dict where the value is an optional message.
        deprecated = getattr(self, "deprecated_args", {})
        if isinstance(deprecated, (set, list, tuple)):
            deprecated_map = {arg: "" for arg in deprecated}
        else:
            deprecated_map = dict(deprecated)

        # Collect all warnings before printing so that the order is deterministic
        warnings_list = []

        # Check CLI arguments
        for arg_name in cli_args:
            if arg_name in deprecated_map:
                msg = f"Argument '{arg_name}' is deprecated"
                if deprecated_map[arg_name]:
                    msg += f": {deprecated_map[arg_name]}"
                msg += " (source: CLI)"
                warnings_list.append(msg)

        # Check answer file arguments
        for arg_name in answer_file_args:
            if arg_name in deprecated_map:
                msg = f"Argument '{arg_name}' is deprecated"
                if deprecated_map[arg_name]:
                    msg += f": {deprecated_map[arg_name]}"
                msg += " (source: answer file)"
                warnings_list.append(msg)

        # Print all warnings
        for warning_msg in warnings_list:
            print(f"WARNING: {warning_msg}")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Try to get parser instance from a variety of possible attributes
    parser = None
    if hasattr(self, "parser_map"):
        parser = self.parser_map.get(command_name)
    if not parser and hasattr(self, "parsers"):
        parser = self.parsers.get(command_name)
    if not parser and hasattr(self, "options_map"):
        # Fallback to using a pre-built options map
        return self.options_map.get(command_name, [])

    if not parser:
        # No parser found for the command, return empty list
        return []

    # Prefer a method that returns option specs if available
    if hasattr(parser, "get_option_specs") and callable(parser.get_option_specs):
        return parser.get_option_specs()

    # Fall back to common attributes that might hold options
    for attr in ("option_specs", "options", "all_options"):
        if hasattr(parser, attr):
            return getattr(parser, attr)

    # If none of the expected attributes exist, return empty list
    return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Retrieve the command configuration
    try:
        command_cfg = self.commands[command_name]
    except (KeyError, AttributeError):
        raise KeyError(f"Command {command_name!r} not found")

    # Options may be stored under different keys; common ones are 'options' and 'args'
    options = None
    for key in ('options', 'args', 'parameters'):
        options = command_cfg.get(key) if isinstance(command_cfg, dict) else None
        if options:
            break

    if not isinstance(options, (dict, list)):
        raise KeyError(f"Command {command_name!r} has no option definitions")

    # If options is a list, look for a matching name
    if isinstance(options, list):
        for opt in options:
            if isinstance(opt, dict) and opt.get('name') == argument_name:
                return opt
        raise KeyError(f"Option {argument_name!r} not found for command {command_name!r}")

    # Otherwise assume a dict of option specs
    try:
        return options[argument_name]
    except KeyError:
        raise KeyError(f"Option {argument_name!r} not found for command {command_name!r}")

