    # Retrieve the command definition
    command = cmd_registry.get(command_name)
    if command is None:
        raise KeyError(f"Command '{command_name}' not found.")
    # Retrieve the options mapping; support common attribute names
    options = getattr(command, "options", None) or getattr(command, "args", None) or getattr(command, "arguments", None)
    if options is None:
        raise AttributeError(f"Command '{command_name}' has no options defined.")
    # Get the specific option spec
