def get_silent_args(self, args):
        """
        list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        # Determine the mapping of argument names to values.
        if isinstance(args, dict):
            arg_map = args
        else:
            try:
                arg_map = vars(args)
            except TypeError:
                return []

        # Retrieve the list/set of names marked as silent from the instance.
        silent_set = getattr(self, 'silent_args', [])
        if not isinstance(silent_set, (set, list, tuple)):
            return []

        # Filter the arguments to return only those that are marked silent.
        return [name for name in silent_set if name in arg_map]

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # If args is None, return an empty list
    if args is None:
        return []

    # Try to convert args to a dictionary
    try:
        arg_dict = vars(args)
    except Exception:
        # Assume args is already a dictionary or iterable of key/value pairs
        arg_dict = args

    silent = []
    if isinstance(arg_dict, dict):
        for key, value in arg_dict.items():
            # Consider arguments starting with '_' or with a None value as "silenced".
            if key.startswith('_') or value is None:
                silent.append(key)
    else:
        # If arg_dict is an iterable of tuples like (key, value)
        for item in arg_dict:
            if isinstance(item, tuple) and len(item) == 2:
                key, value = item
                if key.startswith('_') or value is None:
                    silent.append(key)

    return silent

def validate_requires_args(self, args):
        """Check if all the required arguments have been provided."""
        # Determine the arguments container (dict, Namespace, etc.)
        if isinstance(args, dict):
            arg_values = args
        else:
            arg_values = vars(args)

        # Ensure `self.requires` exists and is iterable
        required = getattr(self, "requires", [])
        if not hasattr(required, "__iter__"):
            raise TypeError("`self.requires` must be an iterable of argument names")

        # Return True only if every required argument is present and not None
        return all(arg_values.get(name) is not None for name in required)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the mapping of provided arguments. Handles dicts and argparse.Namespace-style objects.
    if args is None:
        raise ValueError("No arguments were provided.")
    if isinstance(args, dict):
        provided = args
    elif hasattr(args, '__dict__'):
        provided = vars(args)
    else:
        # Assume args is an iterable of (key, value) pairs
        try:
            provided = dict(args)
        except Exception:
            raise ValueError("Arguments must be a mapping or an iterable of key/value pairs.")
    # Retrieve the set or list of required argument names from the instance.
    required = getattr(self, "_required_args", None)
    if required is None:
        # If no required list is defined, nothing to validate.
        return True
    if not isinstance(required, (set, list, tuple)):
        raise TypeError("self._required_args must be a sequence of argument names.")
    # Find missing required keys
    missing = [name for name in required if name not in provided]
    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required arguments: {missing_str}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                     args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    # Normalize args to a dict for easy lookup
    if not isinstance(args, dict):
        # Attempt to interpret args as a list of (name, value) tuples
        try:
            args = dict(args)
        except Exception:
            args = {}
    # Iterate over options_spec; support both dict mapping name->spec
    # and iterable of spec dicts with a 'name' key.
    if isinstance(options_spec, dict):
        items = options_spec.items()
    else:
        # Assume iterable of spec dicts
        items = [(spec.get('name'), spec) for spec in options_spec if isinstance(spec, dict)]
    for opt_name, opt in items:
        if not opt_name or not opt:
            continue
        # Expect opt to be a dict containing 'required_when'
        if isinstance(opt, dict):
            condition = opt.get('required_when')
            if condition is not None:
                # Determine truthiness of condition
                try:
                    if callable(condition):
                        result = bool(condition(args))
                    elif isinstance(condition, (list, tuple)):
                        # All listed args must be provided and truthy
                        result = all(args.get(name) for name in condition)
                    else:
                        # Treat as a string expression; evaluate in the context of args
                        result = bool(eval(str(condition), {}, args))
                except Exception:
                    result = False
                if result:
                    required.append(opt_name)
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    for spec in options_spec:
        cond = spec.get('required_when')
        if cond is None:
            continue
        cond_met = False
        # Boolean condition
        if isinstance(cond, bool):
            cond_met = cond
        # Callable (lambda, function) condition
        elif callable(cond):
            try:
                cond_met = bool(cond(args))
            except Exception:
                cond_met = False
        # Dictionary of option -> value or list/tuple of values
        elif isinstance(cond, dict):
            cond_met = True
            for opt_key, expected in cond.items():
                actual = args.get(opt_key)
                if isinstance(expected, (list, tuple)):
                    if actual not in expected:
                        cond_met = False
                        break
                else:
                    if actual != expected:
                        cond_met = False
                        break
        # List of conditions (OR logic)
        elif isinstance(cond, (list, tuple)):
            for sub_cond in cond:
                # sub_cond can be dict or callable
                if isinstance(sub_cond, dict):
                    sub_met = True
                    for opt_key, expected in sub_cond.items():
                        actual = args.get(opt_key)
                        if isinstance(expected, (list, tuple)):
                            if actual not in expected:
                                sub_met = False
                                break
                        else:
                            if actual != expected:
                                sub_met = False
                                break
                    if sub_met:
                        cond_met = True
                        break
                elif callable(sub_cond):
                    try:
                        if sub_cond(args):
                            cond_met = True
                            break
                    except Exception:
                        continue
                else:
                    # Any truthy value counts as required
                    if sub_cond:
                        cond_met = True
                        break
        # Fallback: treat any other type as not met
        if cond_met:
            name = spec.get('name')
            if name is None:
                # try 'args' field if present
                name = spec.get('args')
            if name:
                required.append(name)
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required_when_args = []
        # `args` is expected to be a mapping from argument names to their provided values.
        # Build a minimal evaluation context where each argument name becomes a variable
        # and the command name is also available.
        context = {**(args or {}), "command_name": command_name}
        for opt in options_spec or []:
            cond = opt.get("required_when")
            if cond:
                try:
                    # If the condition evaluates to True, add the argument name.
                    if eval(cond, {}, context):
                        name = opt.get("name") or opt.get("arg")
                        if name:
                            required_when_args.append(name)
                except Exception:
                    # Ignore any evaluation errors and continue.
                    continue
        return required_when_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # `self.allowed_lengths` should be a mapping of argument names to their maximum allowed lengths.
    for arg_name, arg_value in args.items():
        max_len = getattr(self, "allowed_lengths", {}).get(arg_name)
        if max_len is not None:
            # Convert value to string for length measurement (handles non-string types).
            val_len = len(str(arg_value))
            if val_len > max_len:
                raise ValueError(
                    f"Argument '{arg_name}' exceeds maximum length of {max_len} "
                    f"(got length {val_len})."
                )

def validate_length_args(self, args):
        """
        Check if value of arguments is not longer than length specified.

        :param args: The received arguments (expected to be a mapping of key to value).
        """
        # Retrieve a mapping of argument names to maximum allowed lengths, if defined.
        length_map = getattr(self, "lengths", None)
        if not length_map:
            return

        for key, value in args.items():
            if key not in length_map:
                continue
            max_len = length_map[key]
            # Skip validation for None values
            if value is None:
                continue
            # Determine the length of the value, converting to string if necessary
            try:
                current_len = len(value)
            except TypeError:
                current_len = len(str(value))
            if current_len > max_len:
                raise ValueError(f"Argument '{key}' length {current_len} exceeds maximum allowed {max_len}.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Mapping of argument names to their valid choices (list/tuple/set or callable)
    choices = getattr(self, 'choices', {})

    # Normalize args to a dictionary of values
    if isinstance(args, dict):
        arg_values = args
    else:
        # Work with argparse.Namespace or similar objects
        arg_values = {k: getattr(args, k, None) for k in dir(args) if not k.startswith("_") and not callable(getattr(args, k, None))}

    # Validate each argument that has defined choices
    for name, allowed in choices.items():
        if name not in arg_values:
            continue  # argument not supplied; skip
        value = arg_values[name]
        if value is None:
            continue  # allow None (may be optional)

        # If allowed is a collection, check membership
        if isinstance(allowed, (list, tuple, set)):
            if value not in allowed:
                raise ValueError(f"Invalid value for argument '{name}': {value}. Allowed: {allowed}")
        else:
            # If allowed is not a simple collection, try a different approach
            try:
                # If it implements __contains__
                if hasattr(allowed, "__contains__") and value not in allowed:
                    raise ValueError(f"Invalid value for argument '{name}': {value}. Allowed: {allowed}")
            except Exception:
                # Fallback: assume callable (predicate) that returns a bool
                if callable(allowed) and not allowed(value):
                    raise ValueError(f"Invalid value for argument '{name}': {value}.")

    return args

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Get argument definitions if stored in self._arguments.
        # If not defined, try self._choices dict mapping argument names to choice lists.
        arg_defs = getattr(self, "_arguments", [])
        # Build a mapping of choices if available in attribute.
        choice_map = getattr(self, "_choices", {})
        for arg_def in arg_defs:
            # Argument definition could be dict or object with attributes.
            name = (
                arg_def.get("name")
                if isinstance(arg_def, dict) else
                getattr(arg_def, "name", None)
            )
            if not name:
                continue
            # Determine choice list for this argument.
            choices = (
                arg_def.get("choices")
                if isinstance(arg_def, dict) and "choices" in arg_def else
                getattr(arg_def, "choices", None)
            )
            if choices is None:
                # Fall back on choice_map if defined.
                choices = choice_map.get(name)
            if not choices:
                continue  # no choices defined, nothing to validate
            if name not in args:
                continue  # argument not provided, skip
            value = args[name]
            # Support container values (list/tuple) for multi-valued arguments.
            if isinstance(value, (list, tuple)):
                if not all(v in choices for v in value):
                    invalid_vals = [v for v in value if v not in choices]
                    raise ValueError(
                        f"Invalid choice(s) {invalid_vals} for argument '{name}'. "
                        f"Allowed choices: {choices}"
                    )
            else:
                if value not in choices:
                    raise ValueError(
                        f"Invalid choice '{value}' for argument '{name}'. "
                        f"Allowed choices: {choices}"
                    )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # If the class provides a mapping of argument names to their valid choices,
    # we iterate over that mapping and validate the supplied arguments accordingly.
    available_choices = getattr(self, "choices", {})
    for arg_name, valid in available_choices.items():
        if arg_name not in args:
            continue
        value = args[arg_name]
        # Support single values and list/tuple of values
        if isinstance(value, (list, tuple)):
            for v in value:
                if v not in valid:
                    raise ValueError(
                        f"Argument '{arg_name}' has invalid choice '{v}'. "
                        f"Allowed choices are: {valid}."
                    )
        else:
            if value not in valid:
                raise ValueError(
                    f"Argument '{arg_name}' has invalid choice '{value}'. "
                    f"Allowed choices are: {valid}."
                )
    return True

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Convert args to a dictionary if it isn't already
    if isinstance(args, dict):
        args_dict = args
    else:
        try:
            args_dict = vars(args)
        except Exception:
            try:
                args_dict = dict(args)
            except Exception:
                # If we cannot interpret args, just skip validation
                return

    # Retrieve available choices mapping (attribute `choices` or `self._choices`)
    choices_map = getattr(self, "choices", None)
    if choices_map is None:
        choices_map = getattr(self, "_choices", None)

    if not isinstance(choices_map, dict):
        # No choices defined, nothing to validate
        return

    for key, value in args_dict.items():
        if key not in choices_map:
            continue
        allowed = choices_map[key]
        # Ensure allowed is iterable
        if not hasattr(allowed, "__iter__"):
            continue
        # Handle values that are iterable (e.g., list, tuple, set)
        if isinstance(value, (list, tuple, set)):
            invalid = [v for v in value if v not in allowed]
            if invalid:
                raise ValueError(
                    f"Invalid choice(s) {invalid} for argument '{key}'. "
                    f"Allowed: {list(allowed)}."
                )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid choice for argument '{key}': {value}. "
                    f"Allowed: {list(allowed)}."
                )

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments. It can be a dictionary containing
            keys for the value and its bounds (min/minimum/min_value, max/maximum/max_value)
            or a tuple/list of the form (min, max, value).
        """
        # Extract min, max, and value from dict if possible
        if isinstance(args, dict):
            # Possible key names for value
            value_keys = ("value", "arg", "parameter")
            min_keys = ("min", "minimum", "min_value")
            max_keys = ("max", "maximum", "max_value")

            value = None
            min_val = None
            max_val = None

            for key in value_keys:
                if key in args:
                    value = args[key]
                    break

            for key in min_keys:
                if key in args:
                    min_val = args[key]
                    break

            for key in max_keys:
                if key in args:
                    max_val = args[key]
                    break
        # Extract from a sequence: (min, max, value)
        elif isinstance(args, (list, tuple)) and len(args) >= 3:
            min_val, max_val, value = args[0], args[1], args[2]
        else:
            # Unsupported format; nothing to validate
            return

        # If any essential component is missing, skip validation
        if value is None or min_val is None or max_val is None:
            return

        # Perform the comparison; raise if out of bounds
        try:
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument value ({value}) is out of bounds "
                    f"[{min_val}, {max_val}]"
                )
        except TypeError as exc:
            # If the values cannot be compared, re-raise with context
            raise TypeError(
                f"Cannot compare values {value!r}, {min_val!r}, and {max_val!r}"
            ) from exc
        return

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments in the form of a dict mapping
                     argument names to their values.
        :return: True if all specified arguments are within the defined
                 minimum/maximum bounds, otherwise False.
        """
        # Ensure the input is a dictionary of argument values
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary of argument values")

        # Retrieve the min and max bounds, if they exist on the instance
        min_bounds = getattr(self, "min_args", {})
        max_bounds = getattr(self, "max_args", {})

        for name, value in args.items():
            # Skip validation if no bounds are defined for this argument
            if name not in min_bounds and name not in max_bounds:
                continue

            # Validate against minimum bound
            if name in min_bounds:
                if value < min_bounds[name]:
                    return False

            # Validate against maximum bound
            if name in max_bounds:
                if value > max_bounds[name]:
                    return False

        return True

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments. Expected to be a mapping
            (e.g. dict or argparse.Namespace) where values are numeric.
        :raises ValueError: If any value is outside the allowed bounds.
        :raises TypeError: If the argument values are not numeric or the
            passed ``args`` object does not support mapping semantics.
        :return: ``True`` if all values are within the bounds.
        """
        # Determine min/max values from the instance. If attributes are not
        # present we simply skip that bound.
        min_val = getattr(self, "min", getattr(self, "minimum", None))
        max_val = getattr(self, "max", getattr(self, "maximum", None))

        # Accept a mapping or an argparse.Namespace (which exposes
        # _get_kwargs). If an incompatible type is passed we raise TypeError.
        if isinstance(args, dict):
            items = args.items()
        elif hasattr(args, "_get_kwargs"):
            items = args._get_kwargs()
        else:
            raise TypeError(
                "args must be a mapping (dict) or an argparse.Namespace-like object"
            )

        for key, value in items:
            if not isinstance(value, (int, float)):
                raise TypeError(
                    f"Argument '{key}' has non-numeric value of type {type(value).__name__}"
                )
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Argument '{key}' value {value} is less than minimum {min_val}"
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Argument '{key}' value {value} is greater than maximum {max_val}"
                )
        return True

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args. Can be a dict or an iterable
        of (key, value) pairs.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Normalise args into a dictionary
    if isinstance(args, dict):
        arg_dict = args
    else:
        arg_dict = {}
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                key, val = item
                arg_dict[key] = val
            else:
                # skip malformed entries
                continue

    # Split based on prefix: "control_" indicates a control argument
    for key, val in arg_dict.items():
        if isinstance(key, str) and key.startswith("control_"):
            # strip the prefix for the resulting control dict
            stripped_key = key[len("control_") :]
            control_args[stripped_key] = val
        else:
            nested_args[key] = val

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args (dict or list of key/value pairs).
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Normalize arguments to dict form if passed as list of tuples
    if isinstance(args, dict):
        arg_dict = args
    else:
        # Assume sequence of (key, value) tuples or (key, value) pairs
        arg_dict = {}
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                arg_dict[key] = value
            else:
                # Ignore malformed entries
                continue

    for key, val in arg_dict.items():
        # Detect control arguments: keys that start with "control_"
        if key.startswith("control_"):
            # Store the key without the prefix
            control_key = key[len("control_") :]
            control_args[control_key] = val
        # Detect custom arguments: keys that start with "custom_"
        # They are stored unmodified in nested_args
        elif key.startswith("custom_"):
            nested_args[key] = val
        else:
            # All other arguments are considered nested arguments
            nested_args[key] = val

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if extra_vars is None:
        return vars_dict

    def _str_to_bool(value):
        if isinstance(value, str):
            lowered = value.lower()
            if lowered in ('true', 'yes', 'on', '1'):
                return True
            if lowered in ('false', 'no', 'off', '0'):
                return False
        return value

    def _str_to_number(value):
        if isinstance(value, str):
            try:
                if '.' in value:
                    return float(value)
                return int(value)
            except ValueError:
                pass
        return value

    def _convert_value(value):
        # Basic conversion: try bool, number, else string
        val = _str_to_bool(value)
        if isinstance(val, bool):
            return val
        val = _str_to_number(val)
        return val

    if isinstance(extra_vars, dict):
        # directly update
        vars_dict.update(extra_vars)
    else:
        # Assume iterable
        try:
            iterator = iter(extra_vars)
        except TypeError:
            # Not iterable, treat as single string
            if isinstance(extra_vars, str) and '=' in extra_vars:
                k, v = extra_vars.split('=', 1)
                vars_dict[k] = _convert_value(v)
            return vars_dict

        for ev in iterator:
            if isinstance(ev, dict):
                vars_dict.update(ev)
            elif isinstance(ev, str) and '=' in ev:
                k, v = ev.split('=', 1)
                vars_dict[k] = _convert_value(v)
            else:
                # Skip invalid or unsupported forms
                continue
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars

        :return: A new dictionary containing the merged variables.
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dict")

        if not extra_vars:
            return vars_dict

        # Allow a single string or a sequence of strings
        if isinstance(extra_vars, str):
            extra_vars = [extra_vars]
        elif not isinstance(extra_vars, (list, tuple, set)):
            raise TypeError("extra_vars must be a string or a list/tuple/set of strings")

        merged = vars_dict.copy()

        for var in extra_vars:
            if not isinstance(var, str):
                raise TypeError("Each extra var must be a string in the form 'key=value'")
            if "=" not in var:
                # Skip items that don't contain a key/value separator
                continue
            key, value = var.split("=", 1)
            key = key.strip()
            value = value.strip()

            # Try to interpret the value as a Python literal if possible
            # (bools, numbers, JSON structures). Fall back to the raw string.
            try:
                # Handle bare booleans
                if value.lower() == "true":
                    parsed_value = True
                elif value.lower() == "false":
                    parsed_value = False
                else:
                    import json
                    parsed_value = json.loads(value)
            except Exception:
                parsed_value = value  # keep as string

            merged[key] = parsed_value

        return merged

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: Updated dictionary
        """
        if not extra_vars:
            return vars_dict

        for var in extra_vars:
            if isinstance(var, dict):
                # Directly update with dict
                vars_dict.update(var)
            elif isinstance(var, str):
                if '=' in var:
                    key, value = var.split('=', 1)
                    key = key.strip()
                    value = value.strip()
                    # Try to interpret the value as JSON; fall back to string
                    try:
                        import json
                        parsed = json.loads(value)
                    except Exception:
                        parsed = value
                    vars_dict[key] = parsed
                else:
                    # If no '=' is present, treat the whole string as a key with empty value
                    vars_dict[var.strip()] = None
            else:
                # Unsupported type, ignore
                continue
        return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in-place.
    By default, all values are left as strings.
    """
    # Retrieve the type mapping for the given parser.  The attribute
    # `_value_type_map` is expected to be a dict of the form:
    # {
    #     'parser_name': {
    #         'arg_name': <type>,   # e.g. int, float, bool, list, str
    #     },
    #     ...
    # }
    type_map = getattr(self, "_value_type_map", {}).get(parser_name, {})
    for key, val in list(values_dict.items()):
        if val is None:
            continue  # nothing to convert
        target_type = type_map.get(key)
        if not target_type:
            continue  # keep as string
        try:
            if target_type is bool:
                # Interpret common truthy strings
                values_dict[key] = val.lower() in ("true", "1", "yes", "y", "on")
            elif target_type is list:
                # Split comma‑separated string into a list
                values_dict[key] = [item.strip() for item in val.split(",")]
            else:
                values_dict[key] = target_type(val)
        except Exception:
            # If the conversion fails, leave the original value unchanged
            pass

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Helper function to convert a single string value
    def _convert_value(val):
        if not isinstance(val, str):
            return val
        v = val.strip()
        if v == '':
            return None
        lowered = v.lower()
        if lowered == 'true':
            return True
        if lowered == 'false':
            return False
        # try bool via numeric representation
        if v in ('1', '0'):
            return bool(int(v))
        # try integer
        if v.lstrip('-').isdigit():
            return int(v)
        # try float
        try:
            return float(v)
        except ValueError:
            pass
        return v

    for key, val in list(values_dict.items()):
        if isinstance(val, str) and ',' in val and not val.startswith('['):
            # treat comma-separated list as list of values
            parts = [p.strip() for p in val.split(',')]
            values_dict[key] = [_convert_value(p) for p in parts]
        else:
            values_dict[key] = _convert_value(val)

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        :return: None (values_dict is modified in place)
        """
        # Optional explicit type specifications for each parser
        # Example format:
        # self._type_specs = {
        #     'main': {'debug': bool, 'count': int, 'ratio': float, 'tags': list},
        #     ...
        # }
        type_specs = getattr(self, "_type_specs", {})
        parser_specs = type_specs.get(parser_name, {})

        for key, value in list(values_dict.items()):
            # If a type is explicitly defined for this key, use it
            if key in parser_specs:
                desired_type = parser_specs[key]
                if desired_type is bool:
                    if isinstance(value, str):
                        val_lower = value.lower()
                        values_dict[key] = val_lower in ("true", "1", "yes", "on")
                    else:
                        values_dict[key] = bool(value)
                elif desired_type in (int, float):
                    try:
                        values_dict[key] = desired_type(value)
                    except (ValueError, TypeError):
                        # keep original if conversion fails
                        pass
                elif desired_type is list:
                    if isinstance(value, str) and "," in value:
                        values_dict[key] = [v.strip() for v in value.split(",")]
                    else:
                        # If already a list or not a comma‑separated string, leave as‑is
                        pass
                else:
                    # For other callable types, attempt to call
                    try:
                        values_dict[key] = desired_type(value)
                    except Exception:
                        pass
                continue

            # No explicit type: heuristic conversion
            if isinstance(value, str):
                val_lower = value.lower()
                if val_lower in ("true", "1", "yes", "on"):
                    values_dict[key] = True
                elif val_lower in ("false", "0", "no", "off"):
                    values_dict[key] = False
                else:
                    # Attempt numeric conversion
                    try:
                        values_dict[key] = int(value)
                        continue
                    except ValueError:
                        pass
                    try:
                        values_dict[key] = float(value)
                        continue
                    except ValueError:
                        pass
                    # Attempt list conversion if comma‑separated
                    if "," in value:
                        values_dict[key] = [v.strip() for v in value.split(",")]
                    # otherwise keep original string
        # No explicit return; values_dict is modified in place
        return None

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        for key, val in values_dict.items():
            if isinstance(val, str):
                stripped = val.strip()
                lower_val = stripped.lower()
                if lower_val == "true":
                    values_dict[key] = True
                elif lower_val == "false":
                    values_dict[key] = False
                else:
                    # Try integer conversion
                    try:
                        values_dict[key] = int(stripped)
                        continue
                    except ValueError:
                        pass
                    # Try float conversion
                    try:
                        values_dict[key] = float(stripped)
                        continue
                    except ValueError:
                        pass
                    # Leave as string if no conversion succeeded
                    values_dict[key] = stripped
        # Return None because values_dict is modified in place (maintaining compatibility)
        return None

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key='', sep='.', result=None):
        if result is None:
            result = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key, sep=sep, result=result)
            else:
                result[new_key] = v
        return result

    plugin_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(plugin_file):
        return {}
    try:
        with open(plugin_file, 'r', encoding='utf-8') as f:
            spec = json.load(f)
    except (IOError, json.JSONDecodeError):
        return {}
    if isinstance(spec, dict):
        return _flatten(spec)
    return {}

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine possible spec file names
    possible_files = ["plugin_spec.yaml", "plugin_spec.yml", "plugin_spec.json"]
    spec_path = None
    for fname in possible_files:
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break

    if spec_path is None:
        return {}

    # Load the spec file (YAML or JSON)
    try:
