def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Locate the spec file (preferring YAML if present, otherwise JSON)
    spec_path = os.path.join(plugin_dir, "plugin.yaml")
    if not os.path.exists(spec_path):
        spec_path = os.path.join(plugin_dir, "plugin.yml")
    if not os.path.exists(spec_path):
        spec_path = os.path.join(plugin_dir, "plugin.json")
    if not os.path.exists(spec_path):
        return {}

    # Load the spec file
    try:
        if spec_path.endswith((".yaml", ".yml")):
            try:
                import yaml
                with open(spec_path, "r", encoding="utf-8") as f:
                    spec = yaml.safe_load(f) or {}
            except Exception:
                # yaml not available; fall back to empty dict
                spec = {}
        else:
            with open(spec_path, "r", encoding="utf-8") as f:
                spec = json.load(f)
    except Exception:
        return {}

    flat = {}

    def _flatten(value, key_prefix=""):
        if isinstance(value, dict):
            for k, v in value.items():
                new_prefix = f"{key_prefix}.{k}" if key_prefix else k
                _flatten(v, new_prefix)
        elif isinstance(value, list):
            for i, item in enumerate(value):
                new_prefix = f"{key_prefix}[{i}]"
