def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    # Normalize root by removing trailing path separators
    while root.endswith('/') or root.endswith('\\'):
        root = root[:-1]
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    # Strip the root prefix
    relative = path[len(root):]
    # Remove leading separators from the remaining part
    while relative.startswith('/') or relative.startswith('\\'):
        relative = relative[1:]
    return relative

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if root == '':
        return path
    if not path.startswith(root):
        raise ValueError(f"root '{root}' is not a prefix of path '{path}'.")
    result = path[len(root):]
    # Normalise any leading slash/backslash
    if result.startswith('/') or result.startswith('\\'):
        result = result[1:]
    return result
